# Dán link drive vào
drive_link = 'https://docs.google.com/spreadsheets/d/1bUyhiiFeBTh8pMpm-BgKhwjnmgI6wh4M/edit?usp=drive_link&ouid=110580722245315873013&rtpof=true&sd=true'

def lam_sach_du_lieu(link):
    try:
        # 1. Chuyển đổi link Drive sang link tải trực tiếp
        file_id = re.search(r'/d/([a-zA-Z0-9_-]+)', link).group(1)
        # Modified: Use export?format=xlsx for direct download of Google Sheets as Excel
        direct_url = f'https://docs.google.com/spreadsheets/d/{file_id}/export?format=xlsx'

        # 2. Đọc file Excel
        # Specify engine='openpyxl' to explicitly tell pandas how to read the file
        df = pd.read_excel(direct_url, engine='openpyxl')

        # 3. Chọn các cột cần dùng
        cols = [
            'url',
            'text',
            'likes',
            'comments',
            'shares',
            'media/0/publish_time',
            'media/0/__typename'
        ]

        df = df[[c for c in cols if c in df.columns]].copy()

        # 4. Chuẩn hoá tên cột
        rename_cols = {
            'url': 'post_url',
            'text': 'post_text',
            'likes': 'likes_count',
            'comments': 'comments_count',
            'shares': 'shares_count',
            'media/0/publish_time': 'publish_time',
            'media/0/__typename': 'post_type'
        }

        df = df.rename(columns=rename_cols)

        # 5. Làm sạch các cột tương tác
        for col in ['likes_count', 'comments_count', 'shares_count']:
            if col in df.columns:
                df[col] = df[col].fillna(0).astype(int)

        # 6. Làm sạch nội dung bài viết
        if 'post_text' in df.columns:
            df['post_text'] = df['post_text'].fillna('')

        # 7. Xử lý thời gian đăng bài
        if 'publish_time' in df.columns:
            # Chuyển timestamp Apify sang datetime
            df['publish_time'] = pd.to_datetime(
                df['publish_time'],
                unit='s',
                errors='coerce'
            )

            # Nội suy missing time:
            # Nếu thiếu thời gian giữa 2 bài thì lấy thời gian nằm giữa bài trước và bài sau
            df['publish_time'] = df['publish_time'].interpolate(method='linear')

            # Nếu thiếu ở đầu/cuối dataset thì lấp bằng giá trị gần nhất
            df['publish_time'] = df['publish_time'].bfill().ffill()

        # 8. Chuẩn hoá loại bài post
        if 'post_type' in df.columns:
            df['post_type'] = df['post_type'].fillna('unknown').astype(str)

        # 9. Xuất file kết quả
        output_file = 'FACEBOOK_VINAMILK_cleaned.xlsx'
        df.to_excel(output_file, index=False)

        print(f"Đã lưu file: {output_file}")
        print(f"Đã xử lý {len(df)} dòng dữ liệu")
        print("Tên cột sau khi chuẩn hoá:")
        print(df.columns.tolist())

        display(df.head())

        # Tải file về máy
        # files.download(output_file) # Removed as per user's request

    except Exception as e:
        print(f"Có lỗi xảy ra: {e}")

# Chạy quy trình
lam_sach_du_lieu(drive_link)

