"""##**YOUTUBE**"""

def make_drive_link(file_id):
    return f'https://docs.google.com/spreadsheets/d/{file_id}/export?format=csv'

def duration_to_sec(d):
    if pd.isna(d): return np.nan
    parts = str(d).split(':')
    try:
        p = [int(x) for x in parts]
        if len(p) == 3: return p[0]*3600 + p[1]*60 + p[2]
        if len(p) == 2: return p[0]*60 + p[1]
        return p[0]
    except: return np.nan

def process_youtube_data(url, company_name, save_filename):
    try:
        urllib.request.urlretrieve(url, save_filename)
        print(f"-> Đã tải thành công file {save_filename} về Colab!")

        df = pd.read_csv(save_filename)

        # --- ĐOẠN SỬA LỖI MẤT HEADER ---
        if 'title' not in df.columns:
            print(f"[*] Phát hiện file {company_name} bị mất dòng tên cột, đang tự động khôi phục...")
            # Lưu lại dòng đầu tiên đang bị lấy nhầm làm header
            first_row_data = df.columns.tolist()

            # Tên cột chuẩn của Youtube
            std_cols = ['title', 'viewCount', 'likes', 'commentsCount', 'date', 'duration', 'type', 'url', 'text', 'numberOfSubscribers', 'channelTotalViews', 'channelTotalVideos', 'hashtags/0', 'hashtags/1', 'hashtags/2', 'hashtags/3', 'hashtags/4', 'hashtags/5', 'hashtags/6', 'hashtags/7', 'hashtags/8', 'hashtags/9']

            # Đổi lại header cho df
            df.columns = std_cols[:len(df.columns)]

            # Khôi phục dòng dữ liệu bị nhầm thành cột
            missing_row_df = pd.DataFrame([first_row_data], columns=df.columns)
            df = pd.concat([missing_row_df, df], ignore_index=True)
        # --------------------------------

    except Exception as e:
        print(f"Lỗi tải/đọc file {company_name}: {e}")
        return None

    df = df[df['title'].notna()].copy()

    cols_yt = ['title', 'viewCount', 'likes', 'commentsCount', 'date', 'duration', 'type', 'url', 'text', 'hashtags/0', 'hashtags/1', 'hashtags/2', 'numberOfSubscribers', 'channelTotalViews', 'channelTotalVideos']
    df = df[[c for c in cols_yt if c in df.columns]]

    df['date'] = pd.to_datetime(df['date'], errors='coerce')
    df['year_month'] = df['date'].dt.to_period('M')
    df['year'] = df['date'].dt.year
    df['month'] = df['date'].dt.month

    df['viewCount'] = pd.to_numeric(df['viewCount'], errors='coerce').fillna(0).astype(int)
    df['commentsCount'] = pd.to_numeric(df['commentsCount'], errors='coerce').fillna(0).astype(int)
    if 'likes' in df.columns:
        df['likes'] = pd.to_numeric(df['likes'], errors='coerce').fillna(0).astype(int)

    if 'duration' in df.columns:
        df['duration_sec'] = df['duration'].apply(duration_to_sec)

    hashtag_cols = ['hashtags/0', 'hashtags/1', 'hashtags/2']
    available_hash_cols = [c for c in hashtag_cols if c in df.columns]
    if available_hash_cols:
        df['all_hashtags'] = df[available_hash_cols].apply(lambda row: [h for h in row if pd.notna(h)], axis=1)
    else:
        df['all_hashtags'] = [[] for _ in range(len(df))]

    df['company'] = company_name
    return df

