VINAMILK_DRIVE_LINK = "https://drive.google.com/file/d/17glPmjOwJ0sCpdZMjwBvQ1Nfg3BBBDvG/view?usp=drive_link"

def get_drive_file_id(url):
    if "/file/d/" in url:
        return url.split("/file/d/")[1].split("/")[0]

    parsed_url = urlparse(url)
    query = parse_qs(parsed_url.query)

    if "id" in query:
        return query["id"][0]

    raise ValueError("Không lấy được file_id. Kiểm tra lại link Google Drive.")


def download_drive_file(drive_link, output_name):
    file_id = get_drive_file_id(drive_link)
    download_url = f"https://drive.google.com/uc?id={file_id}"
    gdown.download(download_url, output_name, quiet=False)
    return output_name


raw_path = download_drive_file(VINAMILK_DRIVE_LINK, "LINKEDIN_VINAMILK.csv")

def read_csv_safely(path):
    encodings = ["utf-8-sig", "utf-8", "latin1"]

    for enc in encodings:
        try:
            return pd.read_csv(path, encoding=enc)
        except Exception:
            pass

    raise ValueError("Không đọc được file CSV. Kiểm tra lại file.")
df = read_csv_safely(raw_path)

def clean_column_names(df):
    df = df.copy()
    df.columns = (
        df.columns
        .str.strip()
        .str.lower()
        .str.replace(r"\s+", "_", regex=True)
        .str.replace(r"[^a-zA-Z0-9_]", "", regex=True)
    )
    return df


def clean_text(text):
    if pd.isna(text):
        return ""

    text = str(text)
    text = text.replace("\n", " ").replace("\r", " ")
    text = re.sub(r"\s+", "", text)
