"""##**APPLESTORE**

###**VINAMILK**
"""

APPSTORE_DRIVE_LINK = "https://drive.google.com/file/d/14lLN7jOaFpTcrNCewwxHnSGX4p0SCDNx/view?usp=drive_link"

def get_drive_file_id(url):
    if "/file/d/" in url:
        return url.split("/file/d/")[1].split("/")[0]

    parsed_url = urlparse(url)
    query = parse_qs(parsed_url.query)

    if "id" in query:
        return query["id"][0]

    raise ValueError("Không lấy được file_id. Kiểm tra lại link Google Drive.")


def download_drive_file(drive_link, output_name):
    file_id = get_drive_file_id(drive_link)
    download_url = f"https://drive.google.com/uc?id={file_id}"
    gdown.download(download_url, output_name, quiet=False)
    return output_name


def read_csv_safely(path):
    encodings = ["utf-8-sig", "utf-8", "latin1"]
    for enc in encodings:
        try:
            return pd.read_csv(path, encoding=enc)
        except Exception:
            pass
    raise ValueError("Không đọc được file CSV. Vui lòng kiểm tra lại file nha.")

def chuyen_id_sang_date_va_hour(review_id):
    """
    Hàm chuyển đổi Review ID của App Store thành cấu trúc Ngày và Giờ riêng biệt.
    Trả về một bộ đôi (date_str, hour_str).
    """
    try:
        rid = float(review_id)
        if pd.isna(rid) or rid <= 0:
            return "Không rõ", "Không rõ"

        anchors = [
            (10000000000, 1640995200),
            (11000000000, 1665000000),
            (12000000000, 1690000000),
            (13000000000, 1713000000),
            (14000000000, 1738000000),
            (15000000000, 1762000000)
        ]

        if rid < anchors[0][0]:
            x1, t1 = anchors[0]
            x2, t2 = anchors[1]
        elif rid > anchors[-1][0]:
            x1, t1 = anchors[-2]
            x2, t2 = anchors[-1]
        else:
            for i in range(len(anchors) - 1):
                if anchors[i][0] <= rid <= anchors[i+1][0]:
                    x1, t1 = anchors[i]
                    x2, t2 = anchors[i+1]
                    break

        timestamp = t1 + (rid - x1) * (t2 - t1) / (x2 - x1)
        dt = pd.to_datetime(timestamp, unit='s', utc=True).tz_convert('Asia/Ho_Chi_Minh')

        date_str = dt.strftime('%d/%m/%Y')
        hour_str = dt.strftime('%H:%M')
        return date_str, hour_str
    except Exception:
        return "Không rõ", "Không rõ"


def lam_sach_text(text):
    if not text or pd.isna(text):
        return ""
    text = str(text).replace('\n', ' ').replace('\r', ' ').replace('\t', ' ')
    text = re.sub(r'\s+', ' ', text)
    return text.strip()


def phan_loai_nhan(stars):
    try:
        stars = int(stars)
        if stars >= 4:
            return "Tích cực"
        elif stars == 3:
            return "Trung lập"
        else:
            return "Tiêu cực"
    except Exception:
        return "Không rõ"


def quy_trinh_tu_dong_chuan_hoa():
    print("TỰ ĐỘNG TẢI FILE TỪ GOOGLE DRIVE...")
    raw_path = download_drive_file(APPSTORE_DRIVE_LINK, "APPSTORE_VINAMILK_RAW.csv")

    print("\n ĐỌC DỮ LIỆU VÀ KHỞI TẠO...")
    df_raw = read_csv_safely(raw_path)

    ten_app = "Vinamilk"
    print(f"Đã nhận dạng App: {ten_app}")
    print("\n BẮT ĐẦU CHUẨN HÓA DỮ LIỆU CHI TIẾT...")

    processed_rows = []
    rows_before = len(df_raw)

    for index, row in df_raw.iterrows():
        stars = row.get("Số sao", row.get("Rating", row.get("rating", 0)))
        review_time_id = row.get("Thời gian ID", row.get("review_id", ""))

        review_date, review_hour = chuyen_id_sang_date_va_hour(review_time_id)

        processed_rows.append({
            "brand": ten_app,
            "platform": "App Store",
            "review_id": str(review_time_id).strip(),
            "username": lam_sach_text(row.get("Người đánh giá (Username)", row.get("username", ""))),
            "rating": int(stars) if str(stars).isdigit() else 0,
            "sentiment_class": phan_loai_nhan(stars),
            "headline": lam_sach_text(row.get("Tiêu đề (Headline)", row.get("headline", ""))),
            "review_detail": lam_sach_text(row.get("Nội dung chi tiết", row.get("content", ""))),
            "app_version": str(row.get("Bối cảnh (Phiên bản App)", row.get("app_version", "Không rõ"))).strip(),
            "country": str(row.get("Quốc gia", "VN")).strip(),
            "profile_link": str(row.get("Link Profile", "")).strip(),
            "review_date": review_date,
            "review_hour": review_hour
        })

    df_processed = pd.DataFrame(processed_rows)

    if "review_id" in df_processed.columns and not df_processed["review_id"].eq("").all():
        df_processed = df_processed.drop_duplicates(subset=["review_id"])
    else:
        df_processed = df_processed.drop_duplicates()

    rows_after = len(df_processed)

    output_csv = "/content/APPSTORE_VINAMILK_CLEANED.csv"
    df_processed.to_csv(output_csv, index=False, encoding='utf-8-sig')

    print("\n ĐÃ CHUẨN HOÁ XONG DATASET APP STORE!")
    print(f"Số dòng ban đầu: {rows_before}")
    print(f"Số dòng sau khi lọc trùng: {rows_after}")
    print(f"Số dòng trùng bị loại bỏ: {rows_before - rows_after}")
    print("\n Đường dẫn lưu file sạch:")
    print(output_csv)

    try:
        display(df_processed.head())
    except NameError:
        print(df_processed.head())

