def normalize_post_type(x):
    x = str(x).lower()
    if "video" in x or "reel" in x:
        return "Video"
    elif "photo" in x or "image" in x or "ảnh" in x:
        return "Ảnh"
    else:
        return "Khác"

df["content_type"] = df["post_type"].apply(normalize_post_type)

summary = df.groupby("content_type").agg(
    so_luong_bai=("content_type", "size"),
    engagement_tb=("total_engagement", "mean")
).sort_values("so_luong_bai", ascending=False)

