bars1 = ax1.bar(x - width/2, summary["so_luong_bai"], width, color=MAIN_COLOR, label="Số lượng bài đăng")
bars2 = ax2.bar(x + width/2, summary["engagement_tb"], width, color=SECONDARY_COLOR, label="Engagement trung bình")

ax1.set_title(f"Vinamilk - Phân bổ loại nội dung và hiệu quả định dạng ({period_label})")
ax1.set_xlabel("Loại nội dung")
ax1.set_ylabel("Số lượng bài đăng")
ax2.set_ylabel("Engagement trung bình")

ax1.set_xticks(x)
ax1.set_xticklabels(summary.index)

ax1.bar_label(bars1, padding=3, fontsize=9)
ax2.bar_label(bars2, padding=3, fontsize=9, fmt="%.0f")

handles1, labels1 = ax1.get_legend_handles_labels()
handles2, labels2 = ax2.get_legend_handles_labels()
ax1.legend(handles1 + handles2, labels1 + labels2, loc="upper center", bbox_to_anchor=(0.5, -0.12), ncol=2)

plt.tight_layout()
plt.show()

