"""### **Biểu đồ: Hiệu suất engagement theo chủ đề nội dung Facebook Vinamilk (2024–2026)**"""

DATA_URL = "https://docs.google.com/spreadsheets/d/1Ov-mG3XppuRb-ArSn5AZLHALEdc7CM39/export?format=xlsx"
MAIN_COLOR = "#0313b0"
SECOND_COLOR = "#A6A6A6"

OUT_DIR = Path("charts_facebook_vinamilk")
OUT_DIR.mkdir(exist_ok=True)

df = pd.read_excel(DATA_URL)

for col in ["likes_count", "comments_count", "shares_count"]:
    df[col] = pd.to_numeric(df[col], errors="coerce").fillna(0)

df["engagement"] = df["likes_count"] + df["comments_count"] + df["shares_count"]

numeric_time = pd.to_numeric(df["publish_time"], errors="coerce")
date_excel = pd.to_datetime(numeric_time, unit="D", origin="1899-12-30", errors="coerce")
date_direct = pd.to_datetime(df["publish_time"], errors="coerce")
df["publish_date"] = date_excel.fillna(date_direct)

df = df.dropna(subset=["publish_date"])
df = df[(df["publish_date"] >= "2024-01-01") & (df["publish_date"] < "2027-01-01")].copy()

def normalize_vi(text):
    text = str(text).lower()
    text = unicodedata.normalize("NFD", text)
    text = "".join(ch for ch in text if unicodedata.category(ch) != "Mn")
    text = text.replace("đ", "d")
    return text

def match_patterns(text, patterns):
    return any(re.search(pattern, text) for pattern in patterns)

df["text_norm"] = df["post_text"].fillna("").apply(normalize_vi)

TOPIC_PATTERNS = {
    "KOL": [r"\bkol\b", r"\bkols\b", r"ca si", r"dien vien", r"nguoi noi tieng", r"dai su thuong hieu", r"hoang dung", r"trang phap"],
    "Gaming": [r"\bgame\b", r"\bgaming\b", r"susu ?hero", r"vu tru tuong tuong", r"vutrutuongtuong"],
    "Minigame": [r"minigame", r"mini game", r"giveaway", r"do vui", r"du doan", r"comment", r"binh luan", r"san qua", r"nhan qua", r"trung qua", r"qua tang", r"rinh qua", r"trung thuong"],
    "Món ăn": [r"mon ngon", r"mon an", r"nau ngon", r"\bnau\b", r"cong thuc", r"sua ong tho", r"ong tho", r"\bbep\b", r"\bche\b", r"\bbanh\b", r"ca phe", r"xa lach", r"cha gio"],
    "Tết": [r"\btet\b", r"\bxuan\b", r"nam moi", r"li xi", r"sum vay", r"doan vien", r"chuc xuan"]
}

topic_rows = []

for topic, patterns in TOPIC_PATTERNS.items():
    mask = df["text_norm"].apply(lambda x: match_patterns(x, patterns))
    sub = df[mask]
    topic_rows.append({
        "topic": topic,
        "posts": len(sub),
        "mean_engagement": sub["engagement"].mean() if len(sub) > 0 else np.nan,
        "median_engagement": sub["engagement"].median() if len(sub) > 0 else np.nan
    })

topic_summary = pd.DataFrame(topic_rows)
topic_summary = topic_summary[topic_summary["posts"] > 0]
topic_summary = topic_summary.sort_values("mean_engagement", ascending=False)

x = np.arange(len(topic_summary))
width = 0.38

plt.figure(figsize=(10, 6))
plt.bar(x - width / 2, topic_summary["mean_engagement"], width, color=MAIN_COLOR, label="Mean engagement")
plt.bar(x + width / 2, topic_summary["median_engagement"], width, color=SECOND_COLOR, label="Median engagement")

for i, row in enumerate(topic_summary.itertuples()):
    y = max(row.mean_engagement, row.median_engagement)
    plt.text(i, y * 1.03, f"n={row.posts}", ha="center", fontsize=9)

plt.title("Hiệu suất engagement theo chủ đề nội dung Facebook Vinamilk (2024–2026)")
plt.xlabel("Chủ đề nội dung")
plt.ylabel("Engagement / bài")
plt.xticks(x, topic_summary["topic"])
plt.legend()
plt.grid(axis="y", alpha=0.25)
plt.tight_layout()
plt.savefig(OUT_DIR / "hinh_3_6_hieu_suat_theo_chu_de.png", dpi=300, bbox_inches="tight")
plt.show()

print(topic_summary)

