"""### **Biểu đồ: Phân bổ nhóm hiệu suất (Low / Medium / High / Very High)**"""

import pandas as pd
import matplotlib.pyplot as plt

MAIN_COLOR = "#0313b0"
PERIOD_MAX = 2026

file_id = "1rxt8U61fiy-MiUjo9atZjhtculxmtmmu"
url = f"https://drive.google.com/uc?export=download&id={file_id}"

df = pd.read_csv(url, sep=";", encoding="utf-8-sig")

df["created_at_vn"] = pd.to_datetime(df["created_at_vn"], errors="coerce")
df = df.dropna(subset=["created_at_vn"])

min_year = df["created_at_vn"].dt.year.min()
start_year = 2020 if min_year < 2020 else min_year

df = df[
    (df["created_at_vn"].dt.year >= start_year) &
    (df["created_at_vn"].dt.year <= PERIOD_MAX)
]

period_label = f"{start_year}–{df['created_at_vn'].dt.year.max()}"

view_col_candidates = [
    "views_count",
    "view_count",
    "play_count",
    "playcount",
    "views",
    "video_views",
    "video_view_count"
]

view_col = None

for col in view_col_candidates:
    if col in df.columns:
        view_col = col
        break

if view_col is None:
    raise ValueError("Không tìm thấy cột lượt xem. Kiểm tra lại tên cột view trong file.")

df[view_col] = pd.to_numeric(df[view_col], errors="coerce")
df = df.dropna(subset=[view_col])

view_bins = [
    0,
    10000,
    50000,
    100000,
    500000,
    1000000,
    5000000,
    float("inf")
]

view_labels = [
    "Dưới 10K",
    "10K–<50K",
    "50K–<100K",
    "100K–<500K",
    "500K–<1M",
    "1M–<5M",
    "Từ 5M trở lên"
]

df["view_range"] = pd.cut(
    df[view_col],
    bins=view_bins,
    labels=view_labels,
    right=False
)

view_distribution = (
    df["view_range"]
    .value_counts()
    .reindex(view_labels)
    .fillna(0)
    .astype(int)
)

view_share = (view_distribution / view_distribution.sum() * 100).round(1)

summary_table = pd.DataFrame({
    "Khoảng lượt xem": view_distribution.index,
    "Số video": view_distribution.values,
    "Tỷ lệ (%)": view_share.values
})

print("BẢNG PHÂN BỔ VIDEO THEO KHOẢNG LƯỢT XEM")
print(summary_table.to_string(index=False))

print("\nTHỐNG KÊ LƯỢT XEM")
print(f"Tổng số video: {len(df):,}")
print(f"Tổng lượt xem: {df[view_col].sum():,.0f}")
print(f"Lượt xem trung bình/video: {df[view_col].mean():,.0f}")
print(f"Trung vị lượt xem/video: {df[view_col].median():,.0f}")
print(f"Video có lượt xem cao nhất: {df[view_col].max():,.0f}")

plt.figure(figsize=(14, 7))

bars = plt.bar(
    summary_table["Khoảng lượt xem"],
    summary_table["Số video"],
    color=MAIN_COLOR,
    width=0.75
)

max_value = summary_table["Số video"].max()

plt.ylim(0, max_value * 1.25)

for bar, pct in zip(bars, summary_table["Tỷ lệ (%)"]):
    height = bar.get_height()
    plt.text(
        bar.get_x() + bar.get_width() / 2,
        height + max_value * 0.03,
        f"{int(height)} video\n{pct}%",
        ha="center",
        va="bottom",
        fontsize=10
    )

plt.title(
    f"Vinamilk - Phân bổ video TikTok theo khoảng lượt xem ({period_label})",
    fontsize=14,
    pad=20
)

plt.xlabel("Khoảng lượt xem", fontsize=12)
plt.ylabel("Số lượng video", fontsize=12)

plt.xticks(rotation=30, ha="right", fontsize=10)
plt.yticks(fontsize=10)

plt.grid(axis="y", alpha=0.3)
plt.tight_layout()
plt.show()

