"""### **Biểu đồ: So sánh Shorts vs Long-form**"""

df_filtered['video_type'] = df_filtered['duration_sec'].apply(lambda x: 'Shorts (<= 60s)' if x <= 60 else 'Long-form (> 60s)')

comparison_data = []
for vtype in ['Shorts (<= 60s)', 'Long-form (> 60s)']:
    df_vt = df_filtered[df_filtered['video_type'] == vtype]
    total_views = df_vt['viewCount'].sum()
    total_likes = df_vt['likes'].sum()
    total_comments = df_vt['commentsCount'].sum()
    er = (total_likes + total_comments) / total_views if total_views > 0 else 0
    comparison_data.append({
        'video_type': vtype,
        'viewCount': df_vt['viewCount'].mean(),
        'engagement_rate': er
    })
comparison_df = pd.DataFrame(comparison_data)

fig, axes = plt.subplots(1, 2, figsize=(14, 6))

vnm_palette = {'Shorts (<= 60s)': '#00A3E0', 'Long-form (> 60s)': '#0313b0'}

