"""### **Biều đồ: View engagement rate theo duration group**"""

def categorize_duration(sec):
    if sec <= 60: return '1. Shorts (<= 1 phút)'
    elif sec <= 300: return '2. Ngắn (1-5 phút)'
    elif sec <= 600: return '3. Trung bình (5-10 phút)'
    else: return '4. Dài (> 10 phút)'

df_filtered['duration_group'] = df_filtered['duration_sec'].apply(categorize_duration)
df_valid_views = df_filtered[df_filtered['viewCount'] > 0].copy()
df_valid_views['engagement_rate'] = ((df_valid_views['likes'] + df_valid_views['commentsCount']) / df_valid_views['viewCount']) * 100

