plt.ylabel('Engagement Rate Trung Bình (%)', fontsize=12, fontweight='bold')

for i, row in df_duration_er.iterrows():
    ax.text(i, row['engagement_rate'] + (df_duration_er['engagement_rate'].max() * 0.02),
            f'{row["engagement_rate"]:.2f}%',
            ha='center', va='bottom', fontsize=11, fontweight='bold', color='#0313b0')

plt.ylim(0, df_duration_er['engagement_rate'].max() * 1.15)
