"""### **Biểu đồ: Tương tác trung bình theo loại nội dung trên LinkedIn (06/2025 - 05/2026)**"""

drive_link = "https://drive.google.com/file/d/1N9vtQ1ng1jzuODmc9UYAf1mEPvp295ju/view?usp=drive_link"
main_color = "#0313b0"
output_dir = "/content/linkedin_54_final"
os.makedirs(output_dir, exist_ok=True)

def get_file_id(link):
    patterns = [r"/d/([a-zA-Z0-9_-]+)", r"id=([a-zA-Z0-9_-]+)"]
    for pattern in patterns:
        match = re.search(pattern, link)
        if match:
            return match.group(1)
    return link

file_id = get_file_id(drive_link)
download_url = f"https://drive.google.com/uc?id={file_id}"
input_file = "/content/linkedin_vinamilk_cleaned.csv"
gdown.download(download_url, input_file, quiet=False)

df = pd.read_csv(input_file)

text_col = "post_content"
df[text_col] = df[text_col].fillna("").astype(str)

for col in ["reactions_count", "comments_count", "reposts_count"]:
    if col not in df.columns:
        df[col] = 0
    df[col] = pd.to_numeric(df[col], errors="coerce").fillna(0)

df["total_engagement"] = df["reactions_count"] + df["comments_count"] + df["reposts_count"]

def clean_text(text):
    text = str(text).lower()
    text = re.sub(r"http\S+|www\S+|lnkd\\.in\S+", " ", text)
    text = re.sub(r"hashtag#", " ", text)
    text = re.sub(r"#", " ", text)
    text = re.sub(r"@\w+", " ", text)
    text = re.sub(r"[^a-zA-ZÀ-ỹ\s]", " ", text)
    text = re.sub(r"\s+", " ", text).strip()
    return text

df["clean_text"] = df[text_col].apply(clean_text)

recruitment_strong = [
    "ứng tuyển", "tuyển dụng", "việc làm", "career", "careers", "job", "jobs",
    "sales trainee", "management trainee", "internship", "intern", "trainee",
    "candidate", "recruitment", "môi trường làm việc", "cơ hội nghề nghiệp",
    "career talk", "gia nhập", "nhân sự", "phỏng vấn"
]

recruitment_support = [
    "đồng đội", "phát triển", "hành trình", "khám phá", "cửa hàng",
    "nhân viên", "đào tạo", "ứng viên", "employee", "employees",
    "talent", "workplace", "corporate life", "lifeatvinamilk", "kinh doanh"
]

product_strong = [
    "green farm", "sữa tươi", "sữa chua", "sữa bột", "fresh milk", "yogurt",
    "probi", "sure prevent", "grow plus", "organic", "sản phẩm mới",
    "product launch", "chất lượng sản phẩm", "sản phẩm dinh dưỡng"
]

product_support = [
    "dinh dưỡng", "sức khỏe", "chất lượng", "ngành sữa", "thực phẩm",
    "chứng nhận", "hương vị", "nguồn dinh dưỡng", "milk", "nutrition"
]

csr_strong = [
    "quỹ sữa", "phát triển bền vững", "net zero", "trao tặng", "từ thiện",
    "sustainability", "sustainable development", "community support"
]

csr_support = [
    "cộng đồng", "môi trường", "trẻ em", "giáo dục", "xã hội", "donation",
    "community", "environment", "children", "education", "phúc lợi cộng đồng"
]

def count_matches(text, keywords):
    return sum(1 for kw in keywords if kw in text)

def classify_content(text):
    rec_strong = count_matches(text, recruitment_strong)
    rec_support = count_matches(text, recruitment_support)
    prod_strong = count_matches(text, product_strong)
    prod_support = count_matches(text, product_support)
    csr_strong_score = count_matches(text, csr_strong)
    csr_support_score = count_matches(text, csr_support)

    recruitment_score = rec_strong * 3 + rec_support
    product_score = prod_strong * 3 + prod_support
    csr_score = csr_strong_score * 4 + csr_support_score

    if csr_strong_score >= 1 and csr_score >= product_score + 2 and csr_score >= recruitment_score + 2:
        return "CSR"

    if product_strong and prod_strong >= 1 and product_score > recruitment_score:
        return "Sản phẩm"

    if product_score >= recruitment_score + 2 and product_score >= 3:
        return "Sản phẩm"

    return "Tuyển dụng"

df["content_type_nlp"] = df["clean_text"].apply(classify_content)

order = ["Tuyển dụng", "Sản phẩm", "CSR"]

summary = df.groupby("content_type_nlp").agg(
    so_bai=("content_type_nlp", "count"),
    tong_tuong_tac=("total_engagement", "sum"),
    tuong_tac_trung_binh=("total_engagement", "mean")
).reindex(order, fill_value=0).reset_index()

summary["tuong_tac_trung_binh"] = summary["tuong_tac_trung_binh"].round(2)
summary["tong_tuong_tac"] = summary["tong_tuong_tac"].round(0).astype(int)

display(summary)

plt.figure(figsize=(8.5, 6))
bars = plt.bar(summary["content_type_nlp"], summary["tuong_tac_trung_binh"], color=main_color)

max_val = summary["tuong_tac_trung_binh"].max()
plt.ylim(0, max_val * 1.25)
plt.xlabel("Loại nội dung")
plt.ylabel("Tương tác trung bình/bài")
plt.grid(axis="y", alpha=0.25)

for i, bar in enumerate(bars):
    height = bar.get_height()
    count_value = int(summary.loc[i, "so_bai"])
    plt.text(
        bar.get_x() + bar.get_width() / 2,
        height + max_val * 0.03,
        f"{height:.2f}\n(n={count_value})",
        ha="center",
        va="bottom",
        fontsize=10
    )

plt.title("Tương tác trung bình theo loại nội dung trên LinkedIn", pad=22)
plt.tight_layout()
output_path = f"{output_dir}/linkedin_tuong_tac_trung_binh_theo_loai_noi_dung_corrected.png"
plt.savefig(output_path, dpi=300, bbox_inches="tight")
plt.show()

print("Đã lưu biểu đồ tại:", output_path)

"""### **Biểu đồ: Tương quan giữa độ dài nội dung và tổng tương tác trên LinkedIn của Vinamilk (06/2025 - 05/2026)**"""

drive_link = "https://drive.google.com/file/d/1uUPei32Gzn9S4ezkJQEOF0pURd59eHFg/view?usp=drive_link"

def extract_file_id(url):
    patterns = [
        r"/d/([a-zA-Z0-9_-]+)",
        r"id=([a-zA-Z0-9_-]+)"
    ]
    for pattern in patterns:
        match = re.search(pattern, url)
        if match:
            return match.group(1)
    raise ValueError("Không lấy được file_id. Kiểm tra lại link Google Drive.")

file_id = extract_file_id(drive_link)
csv_url = f"https://drive.google.com/uc?id={file_id}"
df = pd.read_csv(csv_url)

output_dir = "/content/linkedin_charts_used_in_docs"
os.makedirs(output_dir, exist_ok=True)

for col in ['reactions_count', 'comments_count', 'reposts_count']:
    if col not in df.columns:
        df[col] = 0
    df[col] = pd.to_numeric(df[col], errors='coerce').fillna(0)

df['total_engagement'] = (
    df['reactions_count'] +
    df['comments_count'] +
    df['reposts_count']
)

if 'post_content' in df.columns:
    df['post_content'] = df['post_content'].fillna('').astype(str)
    df['content_length'] = df['post_content'].str.len()
else:
    df['post_content'] = ''
    df['content_length'] = 0

df['date'] = pd.to_datetime(df['date'], errors='coerce')
df = df.dropna(subset=['date'])
df['month_year'] = df['date'].dt.to_period('M').astype(str)

# Vẽ biểu đồ Hình 3.4
x = df['content_length']
y = df['total_engagement']

if x.nunique() > 1 and y.nunique() > 1:
    r, p_value = pearsonr(x, y)
else:
    r, p_value = np.nan, np.nan

plt.figure(figsize=(8, 5))
plt.scatter(x, y, alpha=0.7, color='#0313b0')

if x.nunique() > 1:
    z = np.polyfit(x, y, 1)
    p = np.poly1d(z)
    plt.plot(x, p(x), linestyle='--', color='gray')

plt.title(f'Tương quan giữa độ dài nội dung và tổng tương tác\nPearson r = {r:.2f}, p-value = {p_value:.4f}')
plt.xlabel('Độ dài nội dung')
plt.ylabel('Tổng tương tác')
plt.grid(True, alpha=0.3)
plt.tight_layout()

file_path = f"{output_dir}/Hinh_3_4_Tuong_quan_do_dai_noi_dung_va_tong_tuong_tac.png"
plt.savefig(file_path, dpi=300)
plt.show()
plt.close()

