"""### **Biểu đồ: Top 10 nội dung có repost rate cao nhất trên LinkedIn Vinamilk (06/2025 - 05/2026)**"""

drive_url = "https://drive.google.com/file/d/1N9vtQ1ng1jzuODmc9UYAf1mEPvp295ju/view?usp=drive_link"

file_id_match = re.search(r"/d/([a-zA-Z0-9_-]+)", drive_url)
if file_id_match:
    file_id = file_id_match.group(1)
else:
    file_id = re.search(r"id=([a-zA-Z0-9_-]+)", drive_url).group(1)

output_csv = "linkedin_vinamilk_cleaned.csv"
gdown.download(f"https://drive.google.com/uc?id={file_id}", output_csv, quiet=False)

df = pd.read_csv(output_csv, encoding="utf-8-sig")

df["created_time"] = pd.to_datetime(df["created_time"], errors="coerce")

df["total_engagement"] = (
    df["reactions_count"].fillna(0)
    + df["comments_count"].fillna(0)
    + df["reposts_count"].fillna(0)
)

df["repost_rate"] = df.apply(
    lambda row: (row["reposts_count"] / row["total_engagement"] * 100)
    if row["total_engagement"] > 0 else 0,
    axis=1
)

df_filtered = df[
    (df["total_engagement"] >= 50) &
    (df["reposts_count"] > 0)
].copy()

def clean_text(text):
    if pd.isna(text) or str(text).strip() == "":
        return "Không có nội dung"

    text = fix_text(str(text))
    text = text.replace("\n", " ").replace("\r", " ")
    text = re.sub(r"https?://\S+", "", text)
    text = re.sub(r"#\S+", "", text)
    text = re.sub(r"[^\wÀ-ỹ0-9\s,.:;!?%&/()-]", "", text)
    text = " ".join(text.split())
    return text

def split_by_length(text, length=28, max_lines=3):
    text = clean_text(text)
    text = text[:length * max_lines]
    parts = [text[i:i + length] for i in range(0, len(text), length)]
    return "\n".join(parts[:max_lines])

def make_label(row):
    if pd.notna(row["created_time"]):
        date_label = row["created_time"].strftime("%d/%m/%Y")
    else:
        date_label = "Không rõ ngày"

    content_label = split_by_length(row["post_content"], length=28, max_lines=3)

    return f"{date_label}\n{content_label}"

df_filtered["content_label"] = df_filtered.apply(make_label, axis=1)

top_repost = (
    df_filtered
    .sort_values("repost_rate", ascending=False)
    .head(10)
    .sort_values("repost_rate", ascending=True)
    .copy()
)

top_repost_export = top_repost[
    [
        "created_time",
        "post_content",
        "reactions_count",
        "comments_count",
        "reposts_count",
        "total_engagement",
        "repost_rate"
    ]
].copy()

top_repost_export.to_csv(
    "3_4_7_top10_repost_rate_full_content.csv",
    index=False,
    encoding="utf-8-sig"
)

plt.figure(figsize=(16, 12))

