def classify_sentiment(stars):
    if stars >= 4:
        return "Tích cực"
    elif stars == 3:
        return "Trung lập"
    else:
        return "Tiêu cực"


df_appstore_vnm["sentiment"] = df_appstore_vnm["rating"].apply(classify_sentiment)

sentiment_trend = (
    df_appstore_vnm.groupby(["year_month", "sentiment"])
    .size()
    .unstack(fill_value=0)
)
sentiment_trend_pct = (
    sentiment_trend.div(sentiment_trend.sum(axis=1), axis=0) * 100
)

categories = ["Tiêu cực", "Trung lập", "Tích cực"]
for cat in categories:
    if cat not in sentiment_trend_pct.columns:
        sentiment_trend_pct[cat] = 0.0
sentiment_trend_pct = sentiment_trend_pct[categories]

fig2, ax2 = plt.subplots(figsize=(10, 8))

