review_col = "review_detail"

all_bigrams = []

for text in neg_df[review_col].astype(str):
    text_clean = text.lower()
    for char in [".", ",", "!", "?", '"', "(", ")", "-", "/", ":", "*", "_"]:
        text_clean = text_clean.replace(char, " ")

    words = [w for w in text_clean.split() if w]

    for i in range(len(words) - 1):
        w1 = words[i]
        w2 = words[i + 1]
        if (w1 not in vietnamese_stopwords) and (w2 not in vietnamese_stopwords):
            bigram = f"{w1} {w2}"
            all_bigrams.append(bigram)

top_bigrams = Counter(all_bigrams).most_common(10)

if len(top_bigrams) == 0:
    print("Không tìm thấy cụm từ nào thỏa mãn! Hãy thử bớt các từ trong danh sách 'vietnamese_stopwords' xem sao.")
else:
    df_kws = pd.DataFrame(top_bigrams, columns=["Keyword", "Count"]).sort_values(by="Count", ascending=True)

    fig3, ax3 = plt.subplots(figsize=(10, 6))
    vinamilk_blue = "#0313b0"

    ax3.barh(df_kws["Keyword"], df_kws["Count"], color=vinamilk_blue, height=0.6)

    ax3.set_title(
        "Biểu đồ Top 10 cụm từ xuất hiện nhiều nhất trong các đánh giá tiêu cực (Rating ≤ 2)",
        fontsize=12,
        fontweight="bold",
        pad=15,
        color="#222222",
    )
    ax3.set_xlabel("Số lần xuất hiện (Tần suất)", fontsize=10)
    ax3.set_ylabel("Cụm từ khóa (Keywords)", fontsize=10)

    ax3.set_xlim(0, df_kws["Count"].max() * 1.15)

    for patch in ax3.patches:
        width = patch.get_width()
        height = patch.get_height()
        x = patch.get_x()
        y = patch.get_y()

        if width > 0:
            ax3.annotate(
                f"{int(width)} lần",
                (x + width, y + height / 2.0),
                ha="left",
                va="center",
                xytext=(7, 0),
                textcoords="offset points",
                fontsize=9,
                fontweight="bold",
                color="#222222"
            )

    ax3.grid(axis="x", linestyle="--", alpha=0.3)
    plt.tight_layout()

