for col in ["likes_count", "comments_count", "shares_count"]:
    all_df[col] = pd.to_numeric(all_df[col], errors="coerce").fillna(0)

all_df["engagement"] = all_df["likes_count"] + all_df["comments_count"] + all_df["shares_count"]

summary_df = all_df.groupby("brand").agg(
    total_engagement=("engagement", "sum"),
    avg_engagement_per_post=("engagement", "mean")
).reset_index()

summary_df = summary_df.sort_values("total_engagement", ascending=False)

x = np.arange(len(summary_df))
width = 0.38

