"""### **Biểu đồ: So sánh định dạng nội dung và khả năng lan truyền trên facebook**"""

MAIN_COLOR = "#0313b0"

BRAND_COLORS = {
    "Vinamilk": "#0313b0",
    "TH true MILK": "#8f9cff",
    "Nutifood": "#c5ccff"
}

PERIOD_LABEL = "05/2024–09/2025"

LINKS = {
    "Vinamilk": "https://docs.google.com/spreadsheets/d/1Ov-mG3XppuRb-ArSn5AZLHALEdc7CM39/edit?usp=drive_link&ouid=106209250816449596615&rtpof=true&sd=true",
    "TH true MILK": "https://docs.google.com/spreadsheets/d/1izKJ_rXUxY5tmK3x8lGOH9dLyCBX6e_G/edit?usp=drive_link&ouid=106209250816449596615&rtpof=true&sd=true",
    "Nutifood": "https://docs.google.com/spreadsheets/d/1cycP_bqnKCWGCE3JSs27tJb5D45Lc-OI/edit?usp=drive_link&ouid=106209250816449596615&rtpof=true&sd=true"
}

def read_google_sheet(link):
    file_id = re.search(r"/d/([a-zA-Z0-9_-]+)", link).group(1)
    url = f"https://docs.google.com/spreadsheets/d/{file_id}/export?format=xlsx"
    return pd.read_excel(url)

def normalize_post_type(x):
    x = str(x).lower()
    if "video" in x or "reel" in x:
        return "video"
    elif "photo" in x or "image" in x or "ảnh" in x:
        return "ảnh"
    else:
        return "khác"

dfs = []

for brand, link in LINKS.items():
    df = read_google_sheet(link)
    df["brand"] = brand
    df["publish_time"] = pd.to_datetime(df["publish_time"], errors="coerce")
    df = df.dropna(subset=["publish_time"])
    dfs.append(df)

all_df = pd.concat(dfs, ignore_index=True)

start_date = pd.Timestamp("2024-05-01")
end_date = pd.Timestamp("2025-10-01")

all_df = all_df[(all_df["publish_time"] >= start_date) & (all_df["publish_time"] < end_date)]

for col in ["likes_count", "comments_count", "shares_count"]:
    all_df[col] = pd.to_numeric(all_df[col], errors="coerce").fillna(0)

all_df["engagement"] = all_df["likes_count"] + all_df["comments_count"] + all_df["shares_count"]
all_df["content_type"] = all_df["post_type"].apply(normalize_post_type)

summary = all_df.groupby("brand").agg(
    total_posts=("post_url", "count"),
    video_posts=("content_type", lambda x: (x == "video").sum()),
    total_shares=("shares_count", "sum"),
    total_engagement=("engagement", "sum")
).reset_index()

summary["video_rate"] = summary["video_posts"] / summary["total_posts"] * 100
summary["share_rate"] = summary["total_shares"] / summary["total_engagement"] * 100

plt.figure(figsize=(12, 6))

max_shares = summary["total_shares"].max()

for _, row in summary.iterrows():
    bubble_size = (row["total_shares"] / max_shares) * 900 + 180

    plt.scatter(
        row["video_rate"],
        row["share_rate"],
        s=bubble_size,
        color=BRAND_COLORS[row["brand"]],
        alpha=0.65,
        edgecolors="black",
        linewidth=0.8
    )

    if row["brand"] == "Nutifood":
        x_offset = 0.25
        y_offset = -2.0
    elif row["brand"] == "Vinamilk":
        x_offset = 0.25
        y_offset = 0.7
    else:
        x_offset = 0.25
        y_offset = 0.5

    plt.text(
        row["video_rate"] + x_offset,
        row["share_rate"] + y_offset,
        f"{row['brand']}\n{row['total_shares']:,.0f} shares",
        fontsize=9,
        va="center"
    )

legend_handles = [
    Line2D(
        [0], [0],
        marker="o",
        color="w",
        label=brand,
        markerfacecolor=color,
        markeredgecolor="black",
        markersize=9
    )
    for brand, color in BRAND_COLORS.items()
]

plt.title(f"So sánh định dạng nội dung và khả năng lan truyền trên facebook ({PERIOD_LABEL})")
plt.xlabel("Tỷ lệ video trong tổng số bài (%)")
plt.ylabel("Share rate (%)")

plt.xlim(summary["video_rate"].min() - 2, summary["video_rate"].max() + 4)
plt.ylim(0, summary["share_rate"].max() + 8)

plt.grid(alpha=0.3)

plt.legend(
    handles=legend_handles,
    title="Thương hiệu",
    loc="center left",
    bbox_to_anchor=(1.02, 0.5)
)

plt.tight_layout()
plt.show()

"""### **Biểu đồ: Top hashtag chiến lược dạng bar ngang**"""

MAIN_COLOR = "#0313b0"
PERIOD_LABEL = "05/2024–09/2025"

LINKS = {
    "Vinamilk": "https://docs.google.com/spreadsheets/d/1Ov-mG3XppuRb-ArSn5AZLHALEdc7CM39/edit?usp=drive_link&ouid=106209250816449596615&rtpof=true&sd=true",
    "TH true MILK": "https://docs.google.com/spreadsheets/d/1izKJ_rXUxY5tmK3x8lGOH9dLyCBX6e_G/edit?usp=drive_link&ouid=106209250816449596615&rtpof=true&sd=true",
    "Nutifood": "https://docs.google.com/spreadsheets/d/1cycP_bqnKCWGCE3JSs27tJb5D45Lc-OI/edit?usp=drive_link&ouid=106209250816449596615&rtpof=true&sd=true"
}

def read_google_sheet(link):
    file_id = re.search(r"/d/([a-zA-Z0-9_-]+)", link).group(1)
    url = f"https://docs.google.com/spreadsheets/d/{file_id}/export?format=xlsx"
    return pd.read_excel(url)

dfs = []

for brand, link in LINKS.items():
    df = read_google_sheet(link)
    df["brand"] = brand
    df["publish_time"] = pd.to_datetime(df["publish_time"], errors="coerce")
    df = df.dropna(subset=["publish_time"])
    dfs.append(df)

all_df = pd.concat(dfs, ignore_index=True)

start_date = pd.Timestamp("2024-05-01")
end_date = pd.Timestamp("2025-10-01")

all_df = all_df[(all_df["publish_time"] >= start_date) & (all_df["publish_time"] < end_date)]

hashtag_rows = []

for _, row in all_df.iterrows():
    text = str(row["post_text"])
    hashtags = re.findall(r"#[\wÀ-ỹ]+", text)
    for hashtag in hashtags:
        hashtag_rows.append({
            "brand": row["brand"],
            "hashtag": hashtag
        })

hashtag_df = pd.DataFrame(hashtag_rows)

top_hashtags = (
    hashtag_df.groupby(["brand", "hashtag"])
    .size()
    .reset_index(name="count")
    .sort_values(["brand", "count"], ascending=[True, False])
    .groupby("brand")
    .head(5)
)

top_hashtags["label"] = top_hashtags["brand"] + " - " + top_hashtags["hashtag"]
top_hashtags = top_hashtags.sort_values("count", ascending=True)

plt.figure(figsize=(12, 8))
bars = plt.barh(top_hashtags["label"], top_hashtags["count"], color=MAIN_COLOR)

for bar in bars:
    plt.text(
        bar.get_width(),
        bar.get_y() + bar.get_height()/2,
        f" {bar.get_width():.0f}",
        va="center"
    )

plt.title(f"So sánh top hashtag chiến lược trên facebook ({PERIOD_LABEL})")
plt.xlabel("Số lần xuất hiện")
plt.ylabel("Hashtag")
plt.tight_layout()
plt.show()

"""### **Biểu đồ: So sánh median engagement/post và mức độ ổn định tương tác trên Facebook của 3 thương hiệu Vinamilk, TH true MILK và Nutifood (05/2024–09/2025)**"""

DATA_LINKS = {
    "Vinamilk": "https://docs.google.com/spreadsheets/d/1Ov-mG3XppuRb-ArSn5AZLHALEdc7CM39/export?format=xlsx",
    "TH true MILK": "https://docs.google.com/spreadsheets/d/1izKJ_rXUxY5tmK3x8lGOH9dLyCBX6e_G/export?format=xlsx",
    "Nutifood": "https://docs.google.com/spreadsheets/d/1cycP_bqnKCWGCE3JSs27tJb5D45Lc-OI/export?format=xlsx"
}

BRAND_COLORS = {
    "Vinamilk": "#0313b0",
    "TH true MILK": "#A6A6A6",
    "Nutifood": "#6B7280"
}

