for brand in BRAND_ORDER:
    brand_df = tiktok[tiktok["brand"] == brand]
    all_tags = []
    for item in brand_df["hashtags"].fillna("").astype(str):
        all_tags.extend(extract_hashtags(item))

    counter = Counter(all_tags)
    for tag, count in counter.most_common(5):
        hashtag_rows.append({
            "brand": brand,
            "hashtag": tag,
            "count": count
        })

hashtag_table = pd.DataFrame(hashtag_rows)

