"""###**Biểu đồ: So sánh Save Rate trung vị giữa các brand trên TikTok (07/2025 - 05/2026)**"""

VINAMILK_URL = "https://drive.google.com/file/d/1rxt8U61fiy-MiUjo9atZjhtculxmtmmu/view?usp=drive_link"
TH_URL = "https://drive.google.com/file/d/1aQLJjQfFIrZctAM-oYKH3lPties3s3Xl/view?usp=drive_link"
NUTIFOOD_URL = "https://drive.google.com/file/d/1Dhw1NfybGgspLam2_S-dnmbH9ozpnFIu/view?usp=drive_link"

tiktok_file_configs = {
    "Vinamilk": ("vinamilk.csv", VINAMILK_URL),
    "TH true MILK": ("th_true_milk.csv", TH_URL),
    "Nutifood": ("nutifood.csv", NUTIFOOD_URL)
}

def download_drive(url, output):
    match = re.search(r"/d/([a-zA-Z0-9_-]+)", url)
    file_id = match.group(1) if match else url.split("id=")[-1].split("&")[0]
    gdown.download(f"https://drive.google.com/uc?id={file_id}", output, quiet=False)

def read_file(path):
    return pd.read_csv(path, sep=None, engine="python", encoding="utf-8-sig", on_bad_lines="skip")

all_data = []

for brand, (filename, url) in tiktok_file_configs.items():
    download_drive(url, filename)
    df = read_file(filename)
    df["brand"] = brand
    all_data.append(df)

df = pd.concat(all_data, ignore_index=True)

df["save_count"] = pd.to_numeric(df["save_count"], errors="coerce")
df["view_count"] = pd.to_numeric(df["view_count"], errors="coerce")
df["post_date"] = pd.to_datetime(df["post_date"], errors="coerce")

df = df.dropna(subset=["save_count", "view_count"])
df = df[df["view_count"] > 0]
df["save_rate"] = df["save_count"] / df["view_count"] * 100

date_ranges = df.dropna(subset=["post_date"]).groupby("brand")["post_date"].agg(["min", "max"])

if len(date_ranges) == 3:
    common_start = date_ranges["min"].max()
    common_end = date_ranges["max"].min()
    if common_start <= common_end:
        df = df[(df["post_date"] >= common_start) & (df["post_date"] <= common_end)]

summary = df.groupby("brand").agg(
    median_save_rate=("save_rate", "median"),
    mean_save_rate=("save_rate", "mean"),
    total_videos=("save_rate", "count")
).reset_index()

summary = summary.sort_values("median_save_rate", ascending=True)

plt.figure(figsize=(10, 6))
bars = plt.barh(summary["brand"], summary["median_save_rate"], color="#0313b0")

for bar, value, n in zip(bars, summary["median_save_rate"], summary["total_videos"]):
    plt.text(
        bar.get_width() + summary["median_save_rate"].max() * 0.02,
        bar.get_y() + bar.get_height() / 2,
        f"{value:.3f}% | n={n}",
        va="center",
        fontsize=11
    )

plt.title("So sánh Save Rate trung vị giữa các brand trên TikTok", fontsize=15, fontweight="bold")
plt.xlabel("Median save rate (%)")
plt.ylabel("Brand")
plt.grid(axis="x", alpha=0.25)

if "common_start" in locals() and common_start <= common_end:
    plt.figtext(
        0.01,
        0.01,
        f"Khoảng thời gian chung: {common_start.date()} đến {common_end.date()}",
        fontsize=10
    )

plt.tight_layout(rect=[0, 0.04, 1, 1])
plt.savefig("tiktok_save_rate_by_brand.png", dpi=300, bbox_inches="tight")
plt.show()

summary

