sns.set_theme(style="whitegrid")
brand_colors = {
    'Vinamilk': '#0313b0',
    'TH true MILK': '#00AEEF',
    'Nutifood': '#F05A28'
}

id_vinamilk = '1dNoMoUAbxFva6h8ziudtx-FhANZOGu0n8q1W3RdY1lM'
id_th = '1H2Y7jXo-cdfrGHA6yC4jheq0oFq9s_D7qkGChU2jXhY'
id_nuti = '1646o1Qzp-BrsjK2brB4nXy9L9CtjXWuSaJMzbBfdoAI'

url_vinamilk = f'https://docs.google.com/spreadsheets/d/{id_vinamilk}/export?format=csv'
url_th = f'https://docs.google.com/spreadsheets/d/{id_th}/export?format=csv'
url_nuti = f'https://docs.google.com/spreadsheets/d/{id_nuti}/export?format=csv'

df_vinamilk = pd.read_csv(url_vinamilk)
df_vinamilk['Brand'] = 'Vinamilk'

df_th = pd.read_csv(url_th)
df_th['Brand'] = 'TH true MILK'

df_nuti = pd.read_csv(url_nuti)
df_nuti['Brand'] = 'Nutifood'

df_period = pd.concat([df_vinamilk, df_th, df_nuti], ignore_index=True)

df_period['year'] = pd.to_datetime(df_period['date']).dt.year
df_period = df_period[(df_period['year'] >= 2020) & (df_period['year'] <= 2026)]

def parse_duration(d):
    try:
        parts = str(d).split(':')
        parts = [int(p) for p in parts]
        if len(parts) == 3:
            return parts[0]*3600 + parts[1]*60 + parts[2]
        elif len(parts) == 2:
            return parts[0]*60 + parts[1]
        else:
            return parts[0]
    except:
        return 0

df_period['duration_sec'] = df_period['duration'].apply(parse_duration)

kpi_data = []
shorts_data = []

for brand in ['Vinamilk', 'TH true MILK', 'Nutifood']:
    df_brand = df_period[df_period['Brand'] == brand]

    total_videos = len(df_brand)
    total_views = df_brand['viewCount'].sum()
    avg_views = df_brand['viewCount'].mean() if total_videos > 0 else 0
    total_likes = df_brand['likes'].sum()
    total_comments = df_brand['commentsCount'].sum()
    er_overall = ((total_likes + total_comments) / total_views * 100) if total_views > 0 else 0

    kpi_data.append({
        'Thương hiệu': brand,
        'Tổng số video': total_videos,
        'Tổng lượt xem': total_views,
        'Lượt xem trung bình/video': round(avg_views, 2),
        'Tổng lượt thích': total_likes,
        'Tổng bình luận': total_comments,
        'Engagement rate tổng toàn kênh (%)': round(er_overall, 4)
    })

    df_shorts = df_brand[df_brand['duration_sec'] <= 60]
    df_long = df_brand[df_brand['duration_sec'] > 60]

    pct_shorts_video = (len(df_shorts) / total_videos * 100) if total_videos > 0 else 0
    pct_shorts_view = (df_shorts['viewCount'].sum() / total_views * 100) if total_views > 0 else 0

    shorts_data.append({
        'Thương hiệu': brand,
        '% video Shorts': pct_shorts_video,
        '% view từ Shorts': pct_shorts_view,
        'View TB Shorts': df_shorts['viewCount'].mean() if len(df_shorts) > 0 else 0,
        'View TB Long-form': df_long['viewCount'].mean() if len(df_long) > 0 else 0
    })

df_kpi = pd.DataFrame(kpi_data)
df_shorts_summary = pd.DataFrame(shorts_data)

