linkedin = linkedin.dropna(subset=["date"])

min_dates = linkedin.groupby("brand")["date"].min()
max_dates = linkedin.groupby("brand")["date"].max()

common_start_date = max(min_dates)
common_end_date = min(max_dates)

linkedin = linkedin[
    (linkedin["date"] >= common_start_date) &
    (linkedin["date"] <= common_end_date)
].copy()

if "post_content" not in linkedin.columns:
    linkedin["post_content"] = ""

if "hashtags" not in linkedin.columns:
    linkedin["hashtags"] = ""

linkedin["post_content"] = linkedin["post_content"].fillna("").astype(str)
linkedin["hashtags"] = linkedin["hashtags"].fillna("").astype(str)

def classify_linkedin_content(row):
    text = str(row["post_content"]).lower() + " " + str(row["hashtags"]).lower()

    recruitment_keywords = [
        "career", "careers", "tuyển dụng", "tuyendung", "job", "apply",
        "intern", "internship", "graduate talent", "management trainee",
        "lifeatvinamilk", "recruitment", "hiring", "ứng tuyển", "ung tuyen",
        "cv", "nhân viên", "nhan vien", "talent", "workplace"
    ]

    csr_keywords = [
        "csr", "sustainability", "bền vững", "ben vung", "môi trường",
        "moi truong", "cộng đồng", "cong dong", "xã hội", "xa hoi",
        "green", "net zero", "esg", "trách nhiệm xã hội",
        "trach nhiem xa hoi", "thiện nguyện", "thien nguyen"
    ]

    product_keywords = [
        "sữa", "sua", "milk", "organic", "yogurt", "sữa chua",
        "sua chua", "sản phẩm", "san pham", "dinh dưỡng",
        "dinh duong", "nutrition", "vinamilk care", "growplus",
        "varna", "thức uống", "thuc uong", "th true", "nutifood"
    ]

    brand_keywords = [
        "vinamilk", "th true milk", "nutifood", "thương hiệu",
        "thuong hieu", "brand", "corporate", "doanh nghiệp",
        "doanh nghiep", "văn hóa", "van hoa", "company",
        "award", "giải thưởng", "giai thuong", "tập đoàn", "tap doan"
    ]

    if any(keyword in text for keyword in recruitment_keywords):
        return "Tuyển dụng"
    elif any(keyword in text for keyword in csr_keywords):
        return "CSR"
    elif any(keyword in text for keyword in product_keywords):
        return "Sản phẩm"
    elif any(keyword in text for keyword in brand_keywords):
        return "Thương hiệu"
    else:
        return "Khác"

linkedin["content_type"] = linkedin.apply(classify_linkedin_content, axis=1)

content_order = ["Tuyển dụng", "Thương hiệu", "Sản phẩm", "CSR", "Khác"]

content_count = pd.crosstab(
    linkedin["brand"],
    linkedin["content_type"],
    normalize="index"
) * 100

for col in content_order:
    if col not in content_count.columns:
        content_count[col] = 0

content_count = content_count[content_order]

chart_colors = [MAIN_COLOR] + SECONDARY_COLORS

ax = content_count.plot(
    kind="bar",
    stacked=True,
    figsize=(10, 5),
    color=chart_colors
)

plt.xlabel("Thương hiệu")
plt.ylabel("Tỷ lệ bài đăng (%)")
plt.xticks(rotation=0)
plt.legend(title="Loại nội dung", bbox_to_anchor=(1.05, 1), loc="upper left")
plt.tight_layout()

output_path = os.path.join(output_dir, "4_5_4_linkedin_content_type_structure_by_brand.png")
plt.savefig(output_path, dpi=300, bbox_inches="tight")
plt.show()

print("Đã lưu biểu đồ tại:", output_path)

"""###**Biểu đồ: So sánh Repost Rate giữa 3 thương hiệu trên LinkedIn (08/2025 - 05/2026)**"""

file_links = {
    "Vinamilk": "https://drive.google.com/file/d/1rxt8U61fiy-MiUjo9atZjhtculxmtmmu/view?usp=drive_link",
    "TH true MILK": "https://drive.google.com/file/d/1aQLJjQfFIrZctAM-oYKH3lPties3s3Xl/view?usp=drive_link",
    "Nutifood": "https://drive.google.com/file/d/1Dhw1NfybGgspLam2_S-dnmbH9ozpnFIu/view?usp=drive_link"
}

def get_file_id(link):
    link = str(link).strip()
    patterns = [r"/d/([a-zA-Z0-9_-]+)", r"id=([a-zA-Z0-9_-]+)"]
    for pattern in patterns:
        match = re.search(pattern, link)
        if match:
            return match.group(1)
    return link

def download_file(link, filename):
    file_id = get_file_id(link)
    url = f"https://drive.google.com/uc?id={file_id}"
    gdown.download(url, filename, quiet=False)

def find_col(df, keywords):
    cols = list(df.columns)
    cols_lower = {str(c).lower().strip(): c for c in cols}

    for kw in keywords:
        kw = kw.lower().strip()
        if kw in cols_lower:
            return cols_lower[kw]

    for c in cols:
        c_lower = str(c).lower().strip()
        for kw in keywords:
            if kw.lower().strip() in c_lower:
                return c
    return None

def parse_dates(s):
    s = s.astype(str).str.strip()
    d1 = pd.to_datetime(s, errors="coerce", dayfirst=True)
    d2 = pd.to_datetime(s, errors="coerce", dayfirst=False)
    return d1 if d1.notna().sum() >= d2.notna().sum() else d2

all_data = []

for brand, link in file_links.items():
    filename = brand.replace(" ", "_").replace("true", "true").lower() + ".csv"
    download_file(link, filename)

    df = pd.read_csv(filename, sep=None, engine="python", encoding="utf-8-sig", on_bad_lines="skip")
    df.columns = df.columns.str.strip()

    date_col = find_col(df, ["date", "created_time", "created at", "time", "publish_time", "posted_at"])
    reaction_col = find_col(df, ["reactions_count", "reaction_count", "reactions", "likes", "like_count"])
    comment_col = find_col(df, ["comments_count", "comment_count", "comments"])
    repost_col = find_col(df, ["reposts_count", "repost_count", "reposts", "shares", "share_count"])
    post_col = find_col(df, ["post_id", "id", "url", "post_url", "link"])

    if date_col is None:
        raise ValueError(f"Không tìm thấy cột ngày trong file {brand}. Các cột đang có: {list(df.columns)}")

    df["brand"] = brand
    df["date_parsed"] = parse_dates(df[date_col])
    df["reactions"] = pd.to_numeric(df[reaction_col], errors="coerce").fillna(0) if reaction_col else 0
    df["comments"] = pd.to_numeric(df[comment_col], errors="coerce").fillna(0) if comment_col else 0
    df["reposts"] = pd.to_numeric(df[repost_col], errors="coerce").fillna(0) if repost_col else 0
    df["post_key"] = df[post_col].astype(str) if post_col else np.arange(len(df)).astype(str)

    all_data.append(df[["brand", "date_parsed", "reactions", "comments", "reposts", "post_key"]])

data = pd.concat(all_data, ignore_index=True)
data = data.dropna(subset=["date_parsed"])

min_dates = data.groupby("brand")["date_parsed"].min()
max_dates = data.groupby("brand")["date_parsed"].max()

common_start = min_dates.max()
common_end = max_dates.min()

data = data[(data["date_parsed"] >= common_start) & (data["date_parsed"] <= common_end)].copy()
data["total_engagement"] = data["reactions"] + data["comments"] + data["reposts"]

summary = data.groupby("brand", as_index=False).agg(
    tong_repost=("reposts", "sum"),
    tong_engagement=("total_engagement", "sum"),
    so_bai=("post_key", "count")
)

summary["repost_rate"] = np.where(
    summary["tong_engagement"] > 0,
    summary["tong_repost"] / summary["tong_engagement"] * 100,
    0
)

summary = summary.sort_values("repost_rate", ascending=True)

plt.figure(figsize=(11, 6))
bars = plt.barh(summary["brand"], summary["repost_rate"], color="#0313b0")

max_value = summary["repost_rate"].max()
offset = max_value * 0.03 if max_value > 0 else 0.1

for bar, value in zip(bars, summary["repost_rate"]):
    plt.text(
        bar.get_width() + offset,
        bar.get_y() + bar.get_height() / 2,
        f"{value:.2f}%",
        va="center",
        fontsize=11
    )

plt.title("So sánh Repost Rate giữa 3 thương hiệu trên LinkedIn", fontsize=15, weight="bold")
plt.xlabel("Repost rate (%)")
plt.ylabel("Thương hiệu")
plt.xlim(0, max_value + offset * 8 if max_value > 0 else 1)
plt.grid(axis="x", alpha=0.25)

plt.figtext(
    0.5, -0.03,
    f"Khoảng thời gian chung: {common_start.strftime('%d/%m/%Y')} - {common_end.strftime('%d/%m/%Y')} | Repost rate = Reposts / Tổng engagement",
    ha="center",
    fontsize=10
)

plt.tight_layout()
output_file = "linkedin_repost_rate_3_brand.png"
plt.savefig(output_file, dpi=300, bbox_inches="tight")
plt.show()

