"""###**Biểu đồ: So sánh các vấn đề khách hàng phản ánh nhiều nhất**"""

import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
from collections import Counter

sns.set_style("whitegrid")

VINAMILK_COLOR = "#0313b0"
TH_COLOR = "#8f9cff"

vnm_file_id = "114XnWxq2qgLtulTc_YB0JEtuaz2F2fZC"
th_file_id = "15sWWg5d35uh0E6v6Avc31tnkUQz0p7HR"

vnm_url = f"https://drive.google.com/uc?export=download&id={vnm_file_id}"
th_url = f"https://drive.google.com/uc?export=download&id={th_file_id}"

vnm = pd.read_csv(vnm_url)
th = pd.read_csv(th_url)

print("VINAMILK:", vnm.shape)
print("TH TRUE MILK:", th.shape)

print("\nVINAMILK COLUMNS")
print(vnm.columns.tolist())

print("\nTH TRUE MILK COLUMNS")
print(th.columns.tolist())

rating_col = "rating"
sentiment_col = "sentiment"
review_col = "review_detail"

print("Rating column:", rating_col)
print("Sentiment column:", sentiment_col)
print("Review column:", review_col)

pain_dict = {

    "Lỗi đăng nhập":[
        "login",
        "đăng nhập",
        "dang nhap"
    ],

    "Lỗi OTP":[
        "otp",
        "mã xác thực"
    ],

    "Tích điểm":[
        "điểm",
        "point",
        "tích điểm"
    ],

    "Voucher":[
        "voucher",
        "coupon"
    ],

    "Ứng dụng chậm":[
        "chậm",
        "lag",
        "slow"
    ],

    "Lỗi hệ thống":[
        "lỗi",
        "error",
        "bug",
        "crash"
    ]
}

def count_painpoints(df):

    counter = Counter()

    for text in df[review_col].fillna(""):

        text = str(text).lower()

        for category, keywords in pain_dict.items():

            if any(k in text for k in keywords):
                counter[category] += 1

    return counter

th_pain = count_painpoints(th)
vnm_pain = count_painpoints(vnm)

pain_categories = list(pain_dict.keys())

pain_df = pd.DataFrame({
    "Pain Point": pain_categories,

    "TH true MILK":[
        th_pain.get(x,0)
        for x in pain_categories
    ],

    "Vinamilk":[
        vnm_pain.get(x,0)
        for x in pain_categories
    ]
})

x = np.arange(len(pain_df))

width = 0.35

plt.figure(figsize=(10,6))

plt.barh(
    x-width/2,
    pain_df["TH true MILK"],
    height=0.35,
    color=TH_COLOR,
    label="TH true MILK"
)

plt.barh(
    x+width/2,
    pain_df["Vinamilk"],
    height=0.35,
    color=VINAMILK_COLOR,
    label="Vinamilk"
)

plt.yticks(x, pain_df["Pain Point"])

plt.xlabel("Số lượng phản hồi")
plt.title("So sánh các vấn đề khách hàng phản ánh")
plt.legend()

plt.show()

"""### **Biểu đồ: So sánh cơ cấu phân bố cảm xúc khách hàng**

1.   Mục danh sách
2.   Mục danh sách


"""

sns.set_style("whitegrid")

VINAMILK_COLOR = "#0313b0"
TH_COLOR = "#8f9cff"

vnm_file_id = "114XnWxq2qgLtulTc_YB0JEtuaz2F2fZC"
th_file_id = "15sWWg5d35uh0E6v6Avc31tnkUQz0p7HR"

vnm_url = f"https://drive.google.com/uc?export=download&id={vnm_file_id}"
th_url = f"https://drive.google.com/uc?export=download&id={th_file_id}"

vnm = pd.read_csv(vnm_url)
th = pd.read_csv(th_url)

print("VINAMILK:", vnm.shape)
print("TH TRUE MILK:", th.shape)

print("\nVINAMILK COLUMNS")
print(vnm.columns.tolist())

print("\nTH TRUE MILK COLUMNS")
print(th.columns.tolist())

rating_col = "rating"
sentiment_col = "sentiment"
review_col = "review_detail"

print("Rating column:", rating_col)
print("Sentiment column:", sentiment_col)
print("Review column:", review_col)

def create_sentiment(df):

    df = df.copy()

    df['sentiment'] = df['rating'].apply(
        lambda x:
            'Tích cực' if x >= 4
            else (
                'Trung lập' if x == 3
                else 'Tiêu cực'
            )
    )

    return df

vnm = create_sentiment(vnm)
th = create_sentiment(th)

def sentiment_distribution(df):

    return (
        df['sentiment']
        .value_counts(normalize=True)
        .mul(100)
        .reindex(
            ['Tích cực',
             'Trung lập',
             'Tiêu cực']
        )
        .fillna(0)
    )

th_sent = sentiment_distribution(th)
vnm_sent = sentiment_distribution(vnm)

compare_df = pd.DataFrame({
    'TH true MILK': th_sent,
    'Vinamilk': vnm_sent
}).T

sentiment_colors = {
    'Tích cực': '#4CAF50',
    'Trung lập': '#FFC107',
    'Tiêu cực': '#F44336'
}

fig, ax = plt.subplots(figsize=(10, 6))

compare_df.plot(
    kind='bar',
    stacked=True,
    ax=ax,
    color=[
        sentiment_colors['Tích cực'],
        sentiment_colors['Trung lập'],
        sentiment_colors['Tiêu cực']
    ]
)

for container in ax.containers:

    labels = []

    for value in container.datavalues:

        if value >= 3:
            labels.append(f'{value:.1f}%')
        else:
            labels.append('')

    ax.bar_label(
        container,
        labels=labels,
        label_type='center',
        fontsize=10,
        color='white',
        fontweight='bold'
    )

ax.set_title(
    'So sánh phân bố cảm xúc khách hàng trên App Store',
    fontsize=14,
    fontweight='bold'
)

ax.set_xlabel('')
ax.set_ylabel('Tỷ lệ (%)')

ax.set_ylim(0, 100)

ax.legend(
    title='Nhóm cảm xúc',
    bbox_to_anchor=(1.02, 1),
    loc='upper left'
)

plt.tight_layout()
plt.show()

"""### **Biểu đồ: Biến động Rating sau các bản cập nhật ứng dụng của Vinamilk và TH true MILK (2022–2025)**"""

sns.set_style("whitegrid")

VINAMILK_COLOR = "#0313b0"
TH_COLOR = "#8f9cff"

