"""### **Biểu đồ: So sánh các nhóm vấn đề tiêu cực trong đánh giá người dùng**"""

sns.set_style("whitegrid")

VINAMILK_COLOR = "#0313b0"
TH_COLOR = "#8f9cff"

vnm_file_id = "114XnWxq2qgLtulTc_YB0JEtuaz2F2fZC"
th_file_id = "15sWWg5d35uh0E6v6Avc31tnkUQz0p7HR"

vnm_url = f"https://drive.google.com/uc?export=download&id={vnm_file_id}"
th_url = f"https://drive.google.com/uc?export=download&id={th_file_id}"

vnm = pd.read_csv(vnm_url)
th = pd.read_csv(th_url)

vnm_neg = vnm[(vnm['sentiment_class'] == 'Tiêu cực') | (vnm['rating'] <= 2)].copy()
th_neg = th[(th['sentiment_class'] == 'Tiêu cực') | (th['rating'] <= 2)].copy()

# 2. HÀM PHÂN LOẠI NHÓM VẤN ĐỀ TỰ ĐỘNG DỰA TRÊN TỪ KHÓA (KEYWORDS)
def classify_issue(review):
    if pd.isna(review):
        return "Khác"
    review_lower = str(review).lower()

    # Nhóm 1: Lỗi kỹ thuật, app lag, không đăng nhập/đăng ký được
    if any(kw in review_lower for kw in ['lỗi', 'lag', 'văng', 'đăng nhập', 'đăng ký', 'otp', 'không vào được', 'crash', 'lỏ']):
        return "Lỗi App / Kỹ thuật"
    # Nhóm 2: Vấn đề liên quan tới giao nhận hàng
    elif any(kw in review_lower for kw in ['giao hàng', 'ship', 'trễ', 'chậm', 'hủy đơn', 'bom hàng', 'nhận chậm']):
        return "Giao hàng kém / Trễ đơn"
    # Nhóm 3: Thái độ phục vụ, tổng đài chăm sóc khách hàng
    elif any(kw in review_lower for kw in ['cskh', 'chăm sóc', 'nhân viên', 'tổng đài', 'hotline', 'thái độ', 'gọi không được']):
        return "CSKH / Thái độ phục vụ"
    # Nhóm 4: Khuyến mãi, mã giảm giá, lừa đảo voucher
    elif any(kw in review_lower for kw in ['voucher', 'khuyến mãi', 'mã giảm', 'lừa', 'ảo', 'km']):
        return "Lỗi Khuyến mãi / Voucher"
    else:
        return "Vấn đề khác"

# Áp dụng hàm phân loại vào cột review_detail cho cả 2 brand
vnm_neg['issue_group'] = vnm_neg['review_detail'].apply(classify_issue)
th_neg['issue_group'] = th_neg['review_detail'].apply(classify_issue)

# 3. CHUẨN BỊ DỮ LIỆU ĐỂ VẼ BIỂU ĐỒ TỶ LỆ % (BỞI VÌ SỐ LƯỢNG REVIEW 2 FILE LỆCH NHAU)
vnm_issues = vnm_neg['issue_group'].value_counts(normalize=True).reset_index(name='Percentage')
vnm_issues['Brand'] = 'Vinamilk'

th_issues = th_neg['issue_group'].value_counts(normalize=True).reset_index(name='Percentage')
th_issues['Brand'] = 'TH true MILK'

# Gộp chung dữ liệu của 2 nhãn hàng lại thành 1 bảng bảng tổng hợp
df_compare = pd.concat([vnm_issues, th_issues], ignore_index=True)
df_compare['Percentage'] = df_compare['Percentage'] * 100  # Chuyển đổi sang hệ số %

# Loại bỏ nhóm "Vấn đề khác" nếu muốn biểu đồ tập trung hoàn toàn vào các lỗi cụ thể
df_compare = df_compare[df_compare['issue_group'] != 'Vấn đề khác']


# 4. VẼ BIỂU ĐỒ CỘT GHÉP ĐÔI (GROUPED BAR CHART)
plt.figure(figsize=(12, 6))

ax = sns.barplot(
    data=df_compare,
    x='issue_group',
    y='Percentage',
    hue='Brand',
    palette=[VINAMILK_COLOR, TH_COLOR],
    edgecolor='black',
    linewidth=0.8
)

# Thêm số liệu phần trăm hiển thị trực tiếp trên đỉnh mỗi cột
for p in ax.patches:
    height = p.get_height()
    if height > 0:  # Chỉ hiển thị nhãn nếu cột đó có giá trị
        ax.text(
            p.get_x() + p.get_width() / 2.,
            height + 1.0,
            f'{height:.1f}%',
            ha="center", fontsize=10, fontweight='bold'
        )

# Tinh chỉnh các thông số hiển thị trực quan
plt.title("So Sánh Các Nhóm Vấn Đề Tiêu Cực Trong Đánh Giá Người Dùng", fontsize=14, fontweight='bold', pad=20)
plt.xlabel("Nhóm vấn đề khách hàng khiếu nại", fontsize=12, labelpad=10)
plt.ylabel("Tỷ lệ (%) trên tổng số review tiêu cực", fontsize=12)
plt.ylim(0, df_compare['Percentage'].max() + 10) # Tạo khoảng trống phía trên đỉnh cột để hiển thị chữ
plt.legend(title="Thương hiệu", fontsize=11, title_fontsize=11, loc='upper right')

plt.tight_layout()
plt.savefig("so_sanh_vande_tieucuc.png", dpi=300)
plt.show()

