def standardize_date_column(df, brand_name):
    if 'published_date' in df.columns:
        df['date_col'] = pd.to_datetime(df['published_date'], errors='coerce')
    elif 'date' in df.columns:
        df['date_col'] = pd.to_datetime(df['date'], errors='coerce')
    else:
        raise KeyError(f"Không tìm thấy cột ngày trong DataFrame cho {brand_name}. Vui lòng kiểm tra tên cột.")
    df = df.dropna(subset=['date_col'])
    return df

