"""### **Biểu đồ: Share of voice (2020–2026)**"""

vnm_c = vnm.copy(); vnm_c['brand'] = 'Vinamilk'
th_c  = th.copy();  th_c['brand']  = 'TH true MILK'
nuti_c = nuti.copy(); nuti_c['brand'] = 'Nutifood'

vnm_c['published_date'] = pd.to_datetime(vnm_c['published_date'], format='%m/%d/%Y', errors='coerce')
th_c['published_date'] = pd.to_datetime(th_c['published_date'], format='%m/%d/%Y', errors='coerce')
nuti_c['published_date'] = pd.to_datetime(nuti_c['published_date'], format='%Y-%m-%d', errors='coerce')

df_all = pd.concat([vnm_c, th_c, nuti_c], ignore_index=True)
df_all = df_all.dropna(subset=['published_date'])

df_all = df_all[(df_all['published_date'].dt.year >= 2020) & (df_all['published_date'].dt.year <= 2026)]

df_all['quarter'] = df_all['published_date'].dt.to_period('Q').astype(str)

pivot_sov = df_all.groupby(['quarter', 'brand']).size().unstack(fill_value=0)
pivot_sov_pct = pivot_sov.div(pivot_sov.sum(axis=1), axis=0) * 100
print(pivot_sov.columns)
print(pivot_sov_pct.columns)

fig, ax = plt.subplots(figsize=(12, 6))
colors_brand = {'Vinamilk': '#0313b0', 'TH true MILK': '#f2acc6', 'Nutifood': '#FDDDA6'}
bottom = pd.Series([0.0] * len(pivot_sov_pct), index=pivot_sov_pct.index)

for brand in ['Vinamilk', 'TH true MILK', 'Nutifood']:
    if brand in pivot_sov_pct.columns:
        ax.bar(pivot_sov_pct.index, pivot_sov_pct[brand], bottom=bottom,
               label=brand, color=colors_brand[brand], width=0.8)
        for i, (val, bot) in enumerate(zip(pivot_sov_pct[brand], bottom)):
            if val > 5:
                ax.text(i, bot + val/2, f'{val:.0f}%', ha='center', va='center',
                        fontsize=9, color='white', fontweight='bold')
        bottom = bottom + pivot_sov_pct[brand]

ax.yaxis.set_major_formatter(mtick.PercentFormatter())
ax.set_ylim(0, 100)
ax.set_title('Share of Voice tin tức theo quý (2020-2026)',
             fontsize=13, fontweight='bold')
