"""### **Biểu đồ: So sánh chất lượng nguồn tin (2020-2026)**"""

vnm_c = vnm.copy()
vnm_c['brand'] = 'Vinamilk'
vnm_c['published_date'] = pd.to_datetime(vnm_c['published_date'], format='%m/%d/%Y', errors='coerce')

th_c = th.copy()
th_c['brand'] = 'TH true MILK'
th_c['published_date'] = pd.to_datetime(th_c['published_date'], format='%m/%d/%Y', errors='coerce')

nuti_c = nuti.copy()
nuti_c['brand'] = 'Nutifood'
nuti_c['published_date'] = pd.to_datetime(nuti_c['published_date'], format='%Y-%m-%d', errors='coerce')


df_all = pd.concat([vnm_c, th_c, nuti_c], ignore_index=True)
df_all = df_all.dropna(subset=['published_date'])
df_all = df_all[
    (df_all['published_date'].dt.year >= 2020) &
    (df_all['published_date'].dt.year <= 2026)
]

df_all['source_name'] = df_all['source_name'].astype(str).str.lower()

tier_map = {
    'vnexpress': 'Tier 1',
    'tuoi tre': 'Tier 1',
    'thanhnien': 'Tier 1',
    'dan tri': 'Tier 1',
    'vietnamnet': 'Tier 1',
    'vn economy': 'Tier 1',
    'cafef': 'Tier 1',
    'vtv': 'Tier 1',
    'baotintuc': 'Tier 1',
    'hanoimoi': 'Tier 1',
    'nld.com.vn': 'Tier 1',
    'sggp': 'Tier 1',

    'saigon times': 'Tier 2',
    'ictnews': 'Tier 2',
    'markettimes': 'Tier 2',
    'brandsvietnam': 'Tier 2',
    'genk': 'Tier 2',
    'afamily': 'Tier 2',
    'phunuvietnam': 'Tier 2',
    'doanhnhanvn': 'Tier 2',
    'baodautu': 'Tier 2',

    'blog': 'Tier 3',
    'wordpress': 'Tier 3',
    'facebook': 'Tier 3',
    'youtube': 'Tier 3',
    'tiktok': 'Tier 3',
    'prnasia': 'Tier 3',
    'evn': 'Tier 3',
    'theleader': 'Tier 3'
}

def get_tier(source):
    for k, v in tier_map.items():
        if k in source:
            return v
    return 'Tier 3'

df_all['tier'] = df_all['source_name'].apply(get_tier)
pivot = df_all.groupby(['brand', 'tier']).size().unstack(fill_value=0)

pivot_pct = pivot.div(pivot.sum(axis=1), axis=0) * 100
pivot_pct = pivot_pct.reindex(columns=['Tier 1', 'Tier 2', 'Tier 3'], fill_value=0)

fig, ax = plt.subplots(figsize=(10, 6))

x = np.arange(len(pivot_pct.index))

bottom = np.zeros(len(pivot_pct))

colors = {
    'Tier 1': '#0313b0',
    'Tier 2': '#f2acc6',
    'Tier 3': '#FDDDA6'
}

for tier in ['Tier 1', 'Tier 2', 'Tier 3']:
    ax.bar(
        x,
        pivot_pct[tier],
        bottom=bottom,
        label=tier,
        color=colors[tier],
        width=0.6
    )

    label_color = 'white' if tier == 'Tier 1' else 'black'

    current_bottom = bottom.copy()
    for i, brand_index in enumerate(pivot_pct.index):
        value = pivot_pct.loc[brand_index, tier]
        if value > 0:
            ax.text(
                i,
                current_bottom[i] + value / 2,
                f'{value:.1f}%',
                ha='center',
                va='center',
                fontsize=8,
                color=label_color
            )
    bottom += pivot_pct[tier].values

ax.set_xticks(x)
ax.set_xticklabels(pivot_pct.index)

ax.set_ylim(0, 100)
ax.yaxis.set_major_formatter(mtick.PercentFormatter())

ax.set_title('So sánh chất lượng nguồn tin (2020–2026)', fontweight='bold')
ax.set_xlabel('Thương hiệu')
ax.set_ylabel('Tỷ lệ (%)')

ax.legend(title='Chất lượng nguồn tin')
plt.tight_layout()
plt.show()

"""#**CHƯƠNG 5: PHÂN TÍCH NÂNG CAO**

## **FACEBOOK**
"""

import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
from sklearn.linear_model import LinearRegression

# ======================
# CONFIG
# ======================
url = "https://docs.google.com/spreadsheets/d/1Ov-mG3XppuRb-ArSn5AZLHALEdc7CM39/export?format=xlsx"

START_YEAR = 2020
PERIOD_MAX = 2026

MAIN_COLOR = "#0313b0"
SECONDARY_COLOR_1 = "#888888"

# ======================
# LOAD DATA
# ======================
df = pd.read_excel(url)

df["publish_time"] = pd.to_datetime(df["publish_time"])

# ======================
# FILTER TIME RANGE
# ======================
df = df[
    (df["publish_time"].dt.year >= START_YEAR)
    & (df["publish_time"].dt.year <= PERIOD_MAX)
]

period_label = f"{START_YEAR}–{df['publish_time'].dt.year.max()}"

# ======================
# CREATE ENGAGEMENT
# ======================
df["engagement"] = (
    df["likes_count"]
    + df["comments_count"]
    + df["shares_count"]
)

# ======================
# MONTHLY AGGREGATION
# ======================
monthly = (
    df.groupby(df["publish_time"].dt.to_period("M"))["engagement"]
    .sum()
    .reset_index()
)

monthly["month"] = monthly["publish_time"].astype(str)

# ======================
# LINEAR REGRESSION MODEL
# ======================
X = np.arange(len(monthly)).reshape(-1, 1)
y = monthly["engagement"].values

model = LinearRegression()
model.fit(X, y)

monthly["trend"] = model.predict(X)

# forecast next month
forecast = model.predict([[len(monthly)]])[0]

next_month = str(
    pd.Period(monthly["month"].iloc[-1], freq="M") + 1
)

# ======================
# PLOT
# ======================
plt.figure(figsize=(14, 6))

plt.plot(
    monthly["month"],
    monthly["engagement"],
    marker="o",
    linewidth=2,
    color=MAIN_COLOR,
    label="Actual Engagement"
)

plt.plot(
    monthly["month"],
    monthly["trend"],
    linestyle="--",
    linewidth=2,
    color=SECONDARY_COLOR_1,
    label="Regression Trend"
)

plt.scatter(
    next_month,
    forecast,
    color="red",
    s=120,
    label="Forecast"
)

plt.annotate(
    f"{forecast:,.0f}",
    (next_month, forecast),
    xytext=(0, 10),
    textcoords="offset points",
    ha="center"
)

plt.title(f"Vinamilk - Facebook Engagement Forecast ({period_label})")
plt.xlabel("Month")
plt.ylabel("Engagement")
plt.xticks(rotation=45)
plt.grid(axis="y", alpha=0.3)
plt.legend()
plt.tight_layout()

plt.show()

# ======================
# OUTPUT
# ======================
print(f"Forecast engagement for {next_month}: {forecast:,.0f}")

