def parse_duration(d):
    try:
        parts = str(d).split(':')
        parts = [int(p) for p in parts]
        if len(parts) == 3:
            return parts[0]*3600 + parts[1]*60 + parts[2]
        elif len(parts) == 2:
            return parts[0]*60 + parts[1]
        else:
            return parts[0]
    except:
        return 0

df_vina_adv['duration_sec'] = df_vina_adv['duration'].apply(parse_duration)

