df = pd.read_csv(input_file)

text_col = "post_content"
df[text_col] = df[text_col].astype(str).fillna("")

def clean_text(text):
    text = str(text).lower()
    text = re.sub(r"http\S+|www\S+|lnkd\.in\S+", " ", text)
    text = re.sub(r"hashtag#", " ", text)
    text = re.sub(r"#", " ", text)
    text = re.sub(r"@\w+", " ", text)
    text = re.sub(r"[^a-zA-ZÀ-ỹ\s]", " ", text)
    text = re.sub(r"\s+", " ", text).strip()
    return text

df["clean_text"] = df[text_col].apply(clean_text)

recruitment_keywords = [
    "tuyển dụng", "ứng tuyển", "việc làm", "nhân viên", "thực tập", "trainee",
    "career", "careers", "job", "jobs", "recruitment", "apply", "candidate",
    "employee", "employees", "talent", "workplace", "lifeatvinamilk",
    "corporate life", "corporatelife", "sales trainee", "management trainee",
    "intern", "internship", "môi trường làm việc", "văn hóa", "đội ngũ",
    "nhân sự", "phỏng vấn", "đào tạo", "career talk", "sales", "kỹ năng",
    "chương trình tuyển", "cơ hội nghề", "nghề nghiệp", "gia nhập"
]

product_keywords = [
    "green farm", "organic", "sữa tươi", "sữa chua", "sữa bột",
    "probi", "sure prevent", "grow plus", "fresh milk", "yogurt",
    "nutrition product", "product launch", "dinh dưỡng", "sản phẩm mới",
    "sữa vinamilk", "thực phẩm", "sức khỏe", "chất lượng sản phẩm",
    "nguồn dinh dưỡng", "sản phẩm dinh dưỡng"
]

csr_keywords = [
    "csr", "quỹ sữa", "trao tặng", "từ thiện", "cộng đồng",
    "phát triển bền vững", "môi trường", "trẻ em", "giáo dục",
    "sustainability", "sustainable", "community", "environment",
    "children", "education", "donation", "net zero", "xã hội"
]

def count_keyword_score(text, keywords):
    return sum(1 for kw in keywords if kw in text)

def classify_content(text):
    recruitment_score = count_keyword_score(text, recruitment_keywords)
    product_score = count_keyword_score(text, product_keywords)
    csr_score = count_keyword_score(text, csr_keywords)

    if csr_score >= 1 and csr_score > recruitment_score and csr_score >= product_score:
        return "CSR"
    if product_score >= 2 and product_score > recruitment_score:
        return "Sản phẩm"
    return "Tuyển dụng"

df["content_type_nlp"] = df["clean_text"].apply(classify_content)

word_stopwords = set("""
và là của có cho trong với được các một những này đó khi từ về như để đã sẽ đang
theo tại do trên dưới vào ra hơn rất cũng hoặc nếu vì nên thì mà đến sau trước
cùng không thêm qua năm ngày tháng hôm nay bạn các bạn chúng mình chúng tôi
vinamilk lifeatvinamilk hashtag linkedin việt nam công ty thương hiệu
the and is are was were to of in for on with by from as at an a this that these those
be been being have has had will would can could should may might about into over after
before more most our their your its it they them we us you
""".split())

stop_phrases = [
    "vinamilk việt", "việt nam", "công ty", "thương hiệu", "linkedin vinamilk",
    "hashtag vinamilk", "vinamilk hashtag", "các bạn", "chúng tôi", "hôm nay",
    "đồng hành", "một trong", "trong những", "với những", "của vinamilk",
    "tại vinamilk", "vinamilk luôn", "vinamilk đang", "vinamilk là", "vinamilk đã",
    "the vinamilk", "and the", "for the", "with the", "vinamilk vietnam"
]

def remove_stopwords(text):
    words = str(text).split()
    words = [w for w in words if w not in word_stopwords and len(w) > 2]
    return " ".join(words)

def is_good_phrase(phrase):
    phrase = str(phrase).strip().lower()
    words = phrase.split()

    if len(words) < 2:
        return False
    if any(stop in phrase for stop in stop_phrases):
        return False
    if len(set(words)) == 1:
        return False
    if all(w in word_stopwords for w in words):
        return False
    if any(len(w) <= 2 for w in words):
        return False

    return True

df["tfidf_text"] = df["clean_text"].apply(remove_stopwords)

subset = df[df["content_type_nlp"] == "Tuyển dụng"].copy()

vectorizer = TfidfVectorizer(
    max_features=300,
    ngram_range=(2, 3),
    min_df=1,
    max_df=0.85
)

X = vectorizer.fit_transform(subset["tfidf_text"])
terms = np.array(vectorizer.get_feature_names_out())
scores = np.asarray(X.mean(axis=0)).ravel()

keyword_df = pd.DataFrame({
    "Cụm từ khóa": terms,
    "TF-IDF score": scores
})

keyword_df = keyword_df[keyword_df["Cụm từ khóa"].apply(is_good_phrase)]
keyword_df = keyword_df.sort_values("TF-IDF score", ascending=False).head(10)

display(keyword_df)

plt.figure(figsize=(10, 5.5))
plt.barh(
    keyword_df["Cụm từ khóa"][::-1],
    keyword_df["TF-IDF score"][::-1],
    color=main_color
)
plt.title("Top cụm từ khóa nổi bật trong nhóm nội dung Tuyển dụng")
plt.xlabel("TF-IDF score")
plt.ylabel("Cụm từ khóa")
plt.grid(axis="x", alpha=0.25)
plt.tight_layout()

output_path = f"{output_dir}/hinh_5_4_3_top_cum_tu_khoa_tuyen_dung.png"
plt.savefig(output_path, dpi=300, bbox_inches="tight")
plt.show()

print("Đã lưu biểu đồ tại:", output_path)

