"""##**NEWS**

###**Topic Clustering (TF-IDF + KMeans)**
"""

import matplotlib.pyplot as plt
from underthesea import word_tokenize

vnm['title_tokenized'] = vnm['title'].fillna('').apply(lambda x: word_tokenize(x, format="text"))
texts = vnm['title_tokenized'].tolist()

vietnamese_stopwords = ['của', 'và', 'là', 'có', 'trong', 'cho', 'với', 'được', 'này', 'các', 'tại', 'về']

vectorizer = TfidfVectorizer(max_features=500, min_df=2, stop_words=vietnamese_stopwords)
X = vectorizer.fit_transform(texts)

k = 5
kmeans = KMeans(n_clusters=k, random_state=42, n_init=10)
clusters = kmeans.fit_predict(X)
vnm['cluster_topic'] = clusters

feature_names = vectorizer.get_feature_names_out()
centers = kmeans.cluster_centers_

print("\n-------- TỪ KHÓA ĐẶC TRƯNG CỦA MỖI CLUSTER --------\n")
for i in range(k):
    top_indices = centers[i].argsort()[-10:][::-1]
    top_words = [feature_names[idx] for idx in top_indices]
    n_articles = (clusters == i).sum()
    print(f"Cluster {i} ({n_articles} bài): {', '.join(top_words)}")
    print()

cluster_counts = vnm['cluster_topic'].value_counts().sort_index()
fig, ax = plt.subplots(figsize=(8, 6))
ax.bar(cluster_counts.index.astype(str), cluster_counts.values, color='#0313b0')
ax.set_title('Phân bổ số bài theo cluster tự động (KMeans)', fontsize=12, fontweight='bold')
ax.set_xlabel('Cluster')
ax.set_ylabel('Số bài')
for i, v in enumerate(cluster_counts.values):
    ax.text(i, v + 1, str(v), ha='center', fontweight='bold')
plt.tight_layout()
plt.show()

"""#**CHƯƠNG 7: ĐỀ XUẤT CHIẾN LƯỢC VÀ DỰ BÁO THÁNG TIẾP THEO**

###**7.6. Đề xuất giải quyết Gap 5: Phục hồi vị thế trên nền tảng video (TikTok/YouTube)**

####**Dự báo xu hướng bằng mô hình Moving Average và Linear Trend cho TikTok**
"""

tk_vnm = pd.read_csv('TIKTOK_VINAMILK_cleaned.csv', sep=';', encoding='utf-8-sig')
tk_th = pd.read_csv('TIKTOK_THTRUEMILK_cleaned.csv', sep=';', encoding='utf-8-sig')

tk_vnm['post_date'] = pd.to_datetime(tk_vnm['post_date'])
tk_th['post_date'] = pd.to_datetime(tk_th['post_date'])

tk_vnm_f = tk_vnm[(tk_vnm['post_date'] >= '2025-07-01') & (tk_vnm['post_date'] <= '2026-05-31')].copy()
tk_th_f = tk_th[(tk_th['post_date'] >= '2025-07-01') & (tk_th['post_date'] <= '2026-05-31')].copy()

tk_vnm_f['month'] = tk_vnm_f['post_date'].dt.to_period('M')
tk_th_f['month'] = tk_th_f['post_date'].dt.to_period('M')

vnm_monthly = tk_vnm_f.groupby('month')['view_count'].sum()
th_monthly = tk_th_f.groupby('month')['view_count'].sum()

print("Vinamilk TikTok theo tháng:")
print(vnm_monthly)
print("\nTH true MILK TikTok theo tháng:")
print(th_monthly)

def moving_average_forecast(series, window=3):
    """Trung bình động của N tháng/quý gần nhất"""
    return series.tail(window).mean()

def linear_trend_forecast(series):
    """Hồi quy tuyến tính theo thời gian, dự báo điểm kế tiếp"""
    X = np.arange(len(series)).reshape(-1, 1)
    y = series.values
    model = LinearRegression().fit(X, y)
    next_x = np.array([[len(series)]])
    pred = model.predict(next_x)[0]
    slope = model.coef_[0]
    return pred, slope, model


vnm_ma = moving_average_forecast(vnm_monthly, window=3)
th_ma = moving_average_forecast(th_monthly, window=3)

vnm_lt, vnm_slope, vnm_model = linear_trend_forecast(vnm_monthly)
th_lt, th_slope, th_model = linear_trend_forecast(th_monthly)

print("\n=== DỰ BÁO TIKTOK THÁNG TIẾP THEO ===")
print(f"Vinamilk - Moving Average: {vnm_ma:,.0f} views")
print(f"Vinamilk - Linear Trend: {vnm_lt:,.0f} views | slope: {vnm_slope:,.0f}/tháng")
print(f"TH true MILK - Moving Average: {th_ma:,.0f} views")
print(f"TH true MILK - Linear Trend: {th_lt:,.0f} views | slope: {th_slope:,.0f}/tháng")

months = vnm_monthly.index.astype(str).tolist()
vnm_values = vnm_monthly.values
th_values = th_monthly.values

X = np.arange(len(months)).reshape(-1, 1)

fig, ax = plt.subplots(figsize=(12, 6))
ax.plot(months, vnm_values, marker='o', color='#0057A8', label='Vinamilk (thực tế)', linewidth=2)
ax.plot(months, th_values, marker='o', color='#E30613', label='TH true MILK (thực tế)', linewidth=2)

ax.plot(months, vnm_model.predict(X), '--', color='#0057A8', alpha=0.5, label='Vinamilk (linear trend)')
ax.plot(months, th_model.predict(X), '--', color='#E30613', alpha=0.5, label='TH true MILK (linear trend)')

ax.scatter([len(months)], [vnm_lt], color='#0057A8', marker='*', s=200, zorder=5)
ax.scatter([len(months)], [th_lt], color='#E30613', marker='*', s=200, zorder=5)

ax.set_xticks(list(range(len(months))) + [len(months)])
ax.set_xticklabels(months + ['Tháng tới\n(dự báo)'], rotation=45, ha='right')
ax.set_ylabel('Tổng lượt xem TikTok')
ax.set_title('Dự báo lượt xem TikTok tháng tới — Vinamilk vs TH true MILK', fontsize=12, fontweight='bold')
ax.legend(loc='upper left', fontsize=9)
ax.ticklabel_format(style='plain', axis='y')
plt.tight_layout()
plt.show()

"""####**Dự báo xu hướng bằng mô hình Moving Average và Linear Trend cho Youtube**"""

youtube_vnm = df_vinamilk.copy()
youtube_th = df_th.copy()

youtube_vnm['date'] = pd.to_datetime(youtube_vnm['date'], errors='coerce')
youtube_vnm['viewCount'] = pd.to_numeric(youtube_vnm['viewCount'], errors='coerce')
youtube_th['date'] = pd.to_datetime(youtube_th['date'], errors='coerce')
youtube_th['viewCount'] = pd.to_numeric(youtube_th['viewCount'], errors='coerce')

youtube_vnm['quarter'] = youtube_vnm['date'].dt.to_period('Q')
youtube_th['quarter'] = youtube_th['date'].dt.to_period('Q')

vnm_f = youtube_vnm[(youtube_vnm['date'] >= '2023-01-01') & (youtube_vnm['date'] <= '2026-06-30')]
th_f = youtube_th[(youtube_th['date'] >= '2023-01-01') & (youtube_th['date'] <= '2026-06-30')]

vnm_q = vnm_f.groupby('quarter')['viewCount'].sum()
th_q = th_f.groupby('quarter')['viewCount'].sum()

print("\nVinamilk YouTube theo quý:")
print(vnm_q)
print("\nTH true MILK YouTube theo quý:")
