vnm_model = LinearRegression().fit(X_full, vnm_q.values)
th_model = LinearRegression().fit(X_full, th_q.values)

vnm_yt_pred = vnm_model.predict([[n]])[0]
th_yt_pred = th_model.predict([[n]])[0]

print("\n=== DỰ BÁO YOUTUBE QUÝ TIẾP THEO (giai đoạn 2023Q1–2026Q2) ===")
print(f"Vinamilk - Moving Average (2 quý): {vnm_yt_ma:,.0f} views")
print(f"Vinamilk - Linear Trend: {vnm_yt_pred:,.0f} views | slope: {vnm_model.coef_[0]:,.0f}/quý")
print(f"TH true MILK - Moving Average (2 quý): {th_yt_ma:,.0f} views")
print(f"TH true MILK - Linear Trend: {th_yt_pred:,.0f} views | slope: {th_model.coef_[0]:,.0f}/quý")

quarters = vnm_q.index.astype(str).tolist()
vnm_views_q = vnm_q.values
th_views_q = th_q.values

fig, ax = plt.subplots(figsize=(13, 6))
ax.plot(quarters, vnm_views_q, marker='o', color='#0057A8', label='Vinamilk (thực tế)', linewidth=2, markersize=4)
ax.plot(quarters, th_views_q, marker='o', color='#E30613', label='TH true MILK (thực tế)', linewidth=2, markersize=4)

ax.plot(quarters, vnm_model.predict(X_full), '--', color='#0057A8', alpha=0.5, label='Vinamilk (linear trend)')
ax.plot(quarters, th_model.predict(X_full), '--', color='#E30613', alpha=0.5, label='TH true MILK (linear trend)')

ax.scatter([n], [vnm_yt_pred], color='#0057A8', marker='*', s=250, zorder=5)
ax.scatter([n], [th_yt_pred], color='#E30613', marker='*', s=250, zorder=5)

xtick_labels = quarters + ['Quý tới\n(dự báo)']
ax.set_xticks(list(range(n)) + [n])
ax.set_xticklabels(xtick_labels, rotation=45, ha='right', fontsize=8)
ax.set_ylabel('Tổng lượt xem YouTube')
ax.set_title('Xu hướng và dự báo lượt xem YouTube theo quý — Vinamilk vs TH true MILK\n(2023Q1–2026Q2)', fontsize=12, fontweight='bold')
ax.legend(loc='upper left', fontsize=9)
ax.ticklabel_format(style='plain', axis='y')
plt.tight_layout()
plt.show()